package proxy

import (
	"errors"
	"net/url"
	"reflect"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/gofiber/utils/v2"
	"github.com/gofiber/utils/v2/swar"

	"github.com/gofiber/fiber/v3"

	"github.com/valyala/fasthttp"
)

// Balancer creates a load balancer among multiple upstream servers
func Balancer(config ...Config) fiber.Handler {
	// Set default config
	cfg := configDefault(config...)
	policy := resolvePolicy(cfg.SecurityPolicy)

	// Load balanced client
	lbc := &fasthttp.LBClient{}
	// Note that Servers, Timeout, WriteBufferSize, ReadBufferSize and TLSConfig
	// will not be used if the client are set.
	if cfg.Client == nil {
		// Set timeout
		lbc.Timeout = cfg.Timeout
		// Validate each upstream against the configured policy and build
		// a HostClient per server.
		for _, server := range cfg.Servers {
			u, err := validateUpstreamForBalancer(server, policy)
			if err != nil {
				panic(err)
			}

			client := &fasthttp.HostClient{
				NoDefaultUserAgentHeader: true,
				DisablePathNormalizing:   true,
				Addr:                     u.Host,
				MaxConns:                 cfg.MaxConnsPerHost,

				ReadBufferSize:  cfg.ReadBufferSize,
				WriteBufferSize: cfg.WriteBufferSize,

				TLSConfig: secureTLSConfig(cfg.TLSConfig),

				DialDualStack: cfg.DialDualStack,

				MaxResponseBodySize: cfg.MaxResponseBodySize,
			}
			if u.Scheme == schemeHTTPS {
				client.IsTLS = true
			}
			// When private targets are disallowed, validate the resolved IP
			// at dial time so DNS-rebinding cannot swap a public address for
			// a private one between validation and connection.
			if !policy.AllowPrivateIPs {
				client.Dial = newSSRFDialer(cfg.DialDualStack)
			}

			lbc.Clients = append(lbc.Clients, client)
		}
	} else {
		// Set custom client
		lbc = cfg.Client
	}

	// Return new handler
	return func(c fiber.Ctx) error {
		// Don't execute middleware if Next returns true
		if cfg.Next != nil && cfg.Next(c) {
			return c.Next()
		}

		// Set request and response
		req := c.Request()
		res := c.Response()

		if !policy.KeepHopByHopHeaders {
			if cfg.KeepConnectionHeader {
				stripHopByHopRequestHeaders(req, fiber.HeaderConnection)
			} else {
				stripHopByHopRequestHeaders(req)
			}
		}

		// Modify request
		if cfg.ModifyRequest != nil {
			if err := cfg.ModifyRequest(c); err != nil {
				return err
			}
		}

		if c.App().Config().Immutable {
			req.SetRequestURIBytes(req.RequestURI())
		} else {
			req.SetRequestURI(utils.UnsafeString(req.RequestURI()))
		}

		// The upstream connection speaks HTTP/1.1: reset a protocol token
		// inherited from the inbound request (e.g. "HTTP/2" propagated by
		// the net/http adaptor) so the serialized request line stays valid.
		req.Header.SetProtocol("HTTP/1.1")

		// Forward request
		if err := lbc.Do(req, res); err != nil {
			return err
		}

		if !policy.KeepHopByHopHeaders {
			if cfg.KeepConnectionHeader {
				stripHopByHopResponseHeaders(res, fiber.HeaderConnection)
			} else {
				stripHopByHopResponseHeaders(res)
			}
		}

		// Modify response
		if cfg.ModifyResponse != nil {
			if err := cfg.ModifyResponse(c); err != nil {
				return err
			}
		}

		// Return nil to end proxying if no error
		return nil
	}
}

var defaultClient = &fasthttp.Client{
	NoDefaultUserAgentHeader: true,
	DisablePathNormalizing:   true,
	MaxConnsPerHost:          defaultMaxConnsPerHost,
}

var client atomic.Pointer[fasthttp.Client]

var (
	errNilProxyClientOverride = errors.New("proxy: nil client override passed to Do/Forward")
	errNilGlobalProxyClient   = errors.New("proxy: global client is nil, set a non-nil client with proxy.WithClient")
)

// guardedConfigureClient composes a client's optional pre-existing
// ConfigureClient hook with the dial-time SSRF guard. It is installed on a
// *fasthttp.Client as the bound method value (&guardedConfigureClient{…}).run,
// which fasthttp calls once per HostClient it creates — so the guard is
// present before the first dial to each host and covers both the Dial and
// DialTimeout code paths.
//
// The bound method's code pointer is stable across receivers (unlike a
// closure's), so ensureClientGuarded recognizes an already-guarded client by
// identity — no package-level map keyed by the client, which would pin the
// client and its connection pool for the process lifetime. The struct is
// referenced only from the client's own ConfigureClient field, so it is
// collected together with the client.
type guardedConfigureClient struct {
	// orig is the caller's ConfigureClient hook, or nil. It runs before the
	// guard so the guard wraps whatever Dial/DialTimeout it finally sets —
	// running it after would let a hook that assigns hc.Dial overwrite the
	// guard and reopen the SSRF hole.
	orig func(hc *fasthttp.HostClient) error
}

func (g *guardedConfigureClient) run(hc *fasthttp.HostClient) error {
	if g.orig != nil {
		if err := g.orig(hc); err != nil {
			return err
		}
	}
	installHostClientGuard(hc)
	return nil
}

// guardHookPtr is the code pointer shared by every guardedConfigureClient.run
// method value, used to detect whether a client is already guarded.
var guardHookPtr = reflect.ValueOf((&guardedConfigureClient{}).run).Pointer()

// guardMu serializes the read-modify-write of a client's ConfigureClient in
// ensureClientGuarded, so a concurrent guarder cannot write the field mid
// update or observe it half-installed.
var guardMu sync.Mutex

// ensureClientGuarded installs the SSRF guard on cli via its ConfigureClient
// hook, exactly once (idempotent: a client already carrying the guard method
// is left untouched). It composes with any hook the client already has,
// without retaining a reference to the client. It is invoked at registration
// for the default client (init) and WithClient clients — before either is
// used — and on the dispatch path only for a per-call variadic client (the
// global client is already guarded), so the common no-variadic request path
// never reaches this lock. A handler built with a fixed variadic client (e.g.
// Forward(addr, cli)) does take guardMu once per request; that is a deliberate
// correctness-over-throughput choice (an unlocked fast path would race a
// first-time writer).
//
// Guarantee scope: the default client and WithClient clients are fully
// protected. A client supplied as a per-call variadic argument is guarded on
// first use — but a host it had already dialed keeps its cached, pre-hook
// HostClient, and mutating a client shared with concurrent non-proxy use is
// inherently racy. For a full guarantee with a custom client, register it
// via WithClient before first use, or hand the proxy a dedicated client.
func ensureClientGuarded(cli *fasthttp.Client) {
	guardMu.Lock()
	defer guardMu.Unlock()

	existing := cli.ConfigureClient
	if existing != nil && reflect.ValueOf(existing).Pointer() == guardHookPtr {
		return // already guarded (directly or composed with a user hook)
	}
	cli.ConfigureClient = (&guardedConfigureClient{orig: existing}).run
}

func init() {
	ensureClientGuarded(defaultClient)
	client.Store(defaultClient)
}

// WithClient sets the global proxy client.
// This function should be called before Do and Forward — doing so installs
// the dial-time SSRF guard (via the client's ConfigureClient hook,
// composing with any hook it already carries) before the client dials any
// host, so requests dispatched through it re-validate the resolved IP at
// connect time, matching the default client's behavior.
func WithClient(cli *fasthttp.Client) {
	if cli == nil {
		panic("proxy: WithClient requires a non-nil *fasthttp.Client")
	}

	ensureClientGuarded(cli)
	client.Store(cli)
}

// Forward performs the given http request and fills the given http response.
// This method will return a fiber.Handler
//
// SSRF note: Forward validates the upstream host against the active
// SecurityPolicy up front and, when AllowPrivateIPs is false, re-validates
// the resolved IP at dial time via the guard installed on the dispatching
// client, so a rebinding-capable resolver cannot swap a public answer for
// a private one between validation and connection.
func Forward(addr string, clients ...*fasthttp.Client) fiber.Handler {
	return func(c fiber.Ctx) error {
		c.Request().Header.Set("X-Real-IP", c.IP())
		return Do(c, addr, clients...)
	}
}

// Do performs the given http request and fills the given http response.
// This method can be used within a fiber.Handler
//
// SSRF note: the upstream host is validated against the active
// SecurityPolicy before the request is sent, and when AllowPrivateIPs is
// false the resolved IP is re-validated at dial time by the guard
// installed on the dispatching *fasthttp.Client. The connection therefore
// targets exactly the address that passed the blocklist, so a
// rebinding-capable resolver cannot slip a private IP past the check.
//
// The guard is installed via the client's ConfigureClient hook, which only
// affects HostClients created after installation. The default client and
// WithClient clients are guarded before first use; a client supplied as a
// per-call variadic override is guarded on first use, so a host it had
// already dialed keeps a cached, pre-guard HostClient. For a full guarantee
// with a custom client, register it via WithClient (or pass a dedicated,
// unused client) before first use.
func Do(c fiber.Ctx, addr string, clients ...*fasthttp.Client) error {
	return doAction(c, addr, func(cli *fasthttp.Client, req *fasthttp.Request, resp *fasthttp.Response, _ *url.URL) error {
		return cli.Do(req, resp)
	}, clients...)
}

// DoRedirects performs the given http request and fills the given http response, following up to maxRedirectsCount redirects.
// When the redirect count exceeds maxRedirectsCount, ErrTooManyRedirects is returned.
// This method can be used within a fiber.Handler
//
// Each redirect target is re-validated against the active SecurityPolicy.
// Unless AllowHTTPSDowngrade is enabled, redirects from an HTTPS origin
// to a plaintext HTTP target are rejected with ErrRedirectDowngrade.
//
// SSRF note: every hop's host is validated against the policy, and when
// AllowPrivateIPs is false each dial is re-validated by the guard on the
// dispatching client — so per-hop redirects (including cross-host ones)
// cannot be rebound to a private IP between validation and connection.
func DoRedirects(c fiber.Ctx, addr string, maxRedirectsCount int, clients ...*fasthttp.Client) error {
	policy := currentSecurityPolicy()
	return doActionWithPolicy(c, addr, policy, func(cli *fasthttp.Client, req *fasthttp.Request, resp *fasthttp.Response, u *url.URL) error {
		return followRedirects(cli, req, resp, maxRedirectsCount, u, policy)
	}, clients...)
}

// DoDeadline performs the given request and waits for response until the given deadline.
// This method can be used within a fiber.Handler
//
// SSRF note: same protection as Do — up-front host validation plus the
// dial-time validated-IP guard when AllowPrivateIPs is false.
func DoDeadline(c fiber.Ctx, addr string, deadline time.Time, clients ...*fasthttp.Client) error {
	return doAction(c, addr, func(cli *fasthttp.Client, req *fasthttp.Request, resp *fasthttp.Response, _ *url.URL) error {
		return cli.DoDeadline(req, resp, deadline)
	}, clients...)
}

// DoTimeout performs the given request and waits for response during the given timeout duration.
// This method can be used within a fiber.Handler
//
// SSRF note: same protection as Do — up-front host validation plus the
// dial-time validated-IP guard when AllowPrivateIPs is false.
func DoTimeout(c fiber.Ctx, addr string, timeout time.Duration, clients ...*fasthttp.Client) error {
	return doAction(c, addr, func(cli *fasthttp.Client, req *fasthttp.Request, resp *fasthttp.Response, _ *url.URL) error {
		return cli.DoTimeout(req, resp, timeout)
	}, clients...)
}

// doActionFunc is the per-method callback driven by doActionWithPolicy.
// Receivers are handed the validated *url.URL alongside the request so
// they can avoid re-parsing or re-validating the upstream addr.
type doActionFunc func(cli *fasthttp.Client, req *fasthttp.Request, resp *fasthttp.Response, u *url.URL) error

func doAction(
	c fiber.Ctx,
	addr string,
	action doActionFunc,
	clients ...*fasthttp.Client,
) error {
	return doActionWithPolicy(c, addr, currentSecurityPolicy(), action, clients...)
}

func doActionWithPolicy(
	c fiber.Ctx,
	addr string,
	policy SecurityPolicy,
	action doActionFunc,
	clients ...*fasthttp.Client,
) error {
	globalClient := client.Load()

	cli, err := selectClient(globalClient, clients...)
	if err != nil {
		return err
	}

	// The global client (default or WithClient) is guarded at registration,
	// so only a per-call variadic override needs guarding here. Skipping the
	// global client keeps the common request path free of the guard lock.
	// The guard re-validates the resolved IP at dial time; the
	// validateUpstream call below is only the up-front host check.
	if len(clients) != 0 {
		ensureClientGuarded(cli)
	}

	// Clone addr once at the parse boundary instead of cloning u.Scheme
	// and u.String() individually after the fact. url.Parse fills u's
	// field slices (Scheme/Host/Path/...) with substrings of the input,
	// so if addr is itself a slice of the request buffer (e.g. a caller
	// derived it from c.OriginalURL()), every field in u aliases the
	// same backing array — and SetRequestURI below will overwrite it
	// mid-request. Decoupling u from the request buffer with one clone
	// here covers SetRequestURI/SetSchemeBytes and also the action
	// callback in followRedirects, which inspects u.Host after the
	// SetRequestURI write.
	addrCopy := strings.Clone(addr)
	u, err := validateUpstream(addrCopy, policy)
	if err != nil {
		return err
	}

	req := c.Request()
	res := c.Response()
	originalURL := utils.CopyString(c.OriginalURL())
	defer req.SetRequestURI(originalURL)

	req.SetRequestURI(u.String())
	// SetScheme takes the string directly (fasthttp appends its bytes),
	// avoiding the per-request []byte(u.Scheme) allocation. Re-applying
	// the scheme is required because SetRequestURI keeps the previous
	// scheme when req.isTLS is set — see
	// https://github.com/gofiber/fiber/issues/1762.
	req.URI().SetScheme(u.Scheme)

	if !policy.KeepHopByHopHeaders {
		stripHopByHopRequestHeaders(req)
	}
	// The upstream connection speaks HTTP/1.1: reset a protocol token
	// inherited from the inbound request (e.g. "HTTP/2" propagated by the
	// net/http adaptor) so the serialized request line stays valid.
	req.Header.SetProtocol("HTTP/1.1")
	if err := action(cli, req, res, u); err != nil {
		return err
	}
	if !policy.KeepHopByHopHeaders {
		stripHopByHopResponseHeaders(res)
	}
	return nil
}

// followRedirects implements a redirect loop that re-validates each
// target against policy before issuing the next request. It replaces
// fasthttp.Client.DoRedirects so we can reject HTTPS→HTTP downgrades and
// reapply SSRF checks to caller-controlled Location headers.
//
// initialURL is the validated *url.URL produced by doActionWithPolicy's
// validateUpstream call. Passing it in lets the loop skip a redundant
// re-validation (one url.Parse + one DNS lookup) on entry while still
// guaranteeing every SetRequestURI is fed a string from a
// validateUpstream output — the property CodeQL's go/request-forgery
// query needs to see.
func followRedirects(cli *fasthttp.Client, req *fasthttp.Request, resp *fasthttp.Response, maxRedirects int, initialURL *url.URL, policy SecurityPolicy) error {
	if maxRedirects < 0 {
		maxRedirects = 0
	}
	currentURL := initialURL
	currentHost := currentURL.Host
	for redirects := 0; ; redirects++ {
		// Rendered once per hop: SetRequestURI copies the bytes and
		// resolveRedirect below needs the same string, so sharing it saves
		// a URL.String() allocation on every redirect.
		currentURLStr := currentURL.String()
		req.SetRequestURI(currentURLStr)
		// Re-apply the scheme each hop: SetRequestURI keeps the previous
		// scheme when req.isTLS is set, so a redirect that changes scheme
		// (HTTP→HTTPS upgrade, or HTTPS→HTTP when AllowHTTPSDowngrade is
		// enabled) would otherwise be dispatched with the wrong scheme.
		// See https://github.com/gofiber/fiber/issues/1762.
		req.URI().SetScheme(currentURL.Scheme)
		if err := cli.Do(req, resp); err != nil {
			return err
		}
		status := resp.Header.StatusCode()
		if !fasthttp.StatusCodeIsRedirect(status) {
			return nil
		}
		if redirects >= maxRedirects {
			return fasthttp.ErrTooManyRedirects
		}
		location := resp.Header.Peek(fiber.HeaderLocation)
		if len(location) == 0 {
			return fasthttp.ErrMissingLocation
		}
		nextURL, err := resolveRedirect(currentURLStr, location, policy)
		if err != nil {
			return err
		}
		// POST→GET on 301/302/303 mirrors browser and fasthttp behavior.
		if req.Header.IsPost() && (status == fasthttp.StatusMovedPermanently || status == fasthttp.StatusFound || status == fasthttp.StatusSeeOther) {
			req.Header.SetMethod(fasthttp.MethodGet)
			req.SetBody(nil)
			req.Header.Del(fasthttp.HeaderContentType)
			req.Header.Del(fasthttp.HeaderContentLength)
		}
		// Strip credentials when the redirect crosses to a different host so
		// secrets bound to the original origin are not leaked to a third
		// party (RFC 9110 §15.4 advisory; matches browser behavior).
		if !utils.EqualFold(nextURL.Host, currentHost) {
			stripCrossHostHeaders(req)
			currentHost = nextURL.Host
		}
		currentURL = nextURL
	}
}

// crossHostSensitiveHeaders lists headers that carry credentials bound to
// a specific origin and must not survive a redirect to a different host.
var crossHostSensitiveHeaders = []string{
	fiber.HeaderAuthorization,
	fiber.HeaderProxyAuthorization,
	fiber.HeaderCookie,
}

func stripCrossHostHeaders(req *fasthttp.Request) {
	for _, h := range crossHostSensitiveHeaders {
		req.Header.Del(h)
	}
}

// ctlOrDELMask marks the lanes of w holding control bytes that must not
// appear in a redirect Location value: anything < 0x20 (including HTAB) or
// DEL. Bytes >= 0x80 are never marked; they are handled by URI parsing, not
// header-injection checks.
func ctlOrDELMask(w uint64) uint64 {
	return swar.MatchRangeMask(w, 0x00, 0x1f) | swar.MatchByteMask(w, 0x7f)
}

// containsCTLOrDEL reports whether b holds any byte ctlOrDELMask matches.
// It scans eight bytes at a time, finishing inputs of 8+ bytes with one
// overlapping word; shorter inputs are checked byte-wise.
func containsCTLOrDEL(b []byte) bool {
	n := len(b)
	i := 0
	for ; i+swar.WordLen <= n; i += swar.WordLen {
		if ctlOrDELMask(swar.Load8(b, i)) != 0 {
			return true
		}
	}
	if i == n {
		return false
	}
	if n >= swar.WordLen {
		return ctlOrDELMask(swar.Load8(b, n-swar.WordLen)) != 0
	}
	for ; i < n; i++ {
		if b[i] < 0x20 || b[i] == 0x7f {
			return true
		}
	}
	return false
}

// resolveRedirect parses a redirect target relative to the current URL
// and applies the SecurityPolicy. CRLF and other control bytes are
// rejected to prevent header injection via Location. The returned value
// is the validated *url.URL produced by validateUpstream, so callers
// pass it straight into network sinks without re-parsing user-controlled
// strings.
func resolveRedirect(currentURL string, location []byte, policy SecurityPolicy) (*url.URL, error) {
	if containsCTLOrDEL(location) {
		return nil, fasthttp.ErrorInvalidURI
	}
	uri := fasthttp.AcquireURI()
	defer fasthttp.ReleaseURI(uri)
	uri.Update(currentURL)
	// previousScheme is at most "https" (5 bytes). A stack-sized scratch
	// buffer holds it without escaping to the heap, eliminating the
	// per-hop allocation that the previous append([]byte(nil), ...)
	// pattern produced.
	var schemeBuf [8]byte
	previousScheme := append(schemeBuf[:0], uri.Scheme()...)
	uri.UpdateBytes(location)
	if len(uri.Host()) == 0 {
		return nil, fasthttp.ErrorInvalidURI
	}
	target, err := validateUpstream(uri.String(), policy)
	if err != nil {
		return nil, err
	}
	if !policy.AllowHTTPSDowngrade && utils.EqualFold(previousScheme, httpsSchemeBytes) && target.Scheme == schemeHTTP {
		return nil, ErrRedirectDowngrade
	}
	return target, nil
}

func selectClient(globalClient *fasthttp.Client, clients ...*fasthttp.Client) (*fasthttp.Client, error) {
	if len(clients) != 0 {
		if clients[0] == nil {
			return nil, errNilProxyClientOverride
		}

		return clients[0], nil
	}

	if globalClient == nil {
		return nil, errNilGlobalProxyClient
	}

	return globalClient, nil
}

// DomainForward performs an http request based on the given domain and populates the given http response.
// This method will return a fiber.Handler.
//
// The upstream addr is validated at handler construction: scheme allowlist,
// SSRF block, and URL parsing all run once. Unlike Balancer (which defers
// DNS to dial time to survive transient resolver failures at startup), this
// construction check resolves the host, so a misconfigured or unresolvable
// addr panics at startup instead of failing per request. Each request also
// re-validates the host against the current policy before dispatch.
//
// SSRF note: the per-request validation is an up-front host check, and
// when AllowPrivateIPs is false the dispatching client's dial-time guard
// re-validates the resolved IP at connect time — so a rebinding-capable
// resolver cannot reach a private address through this handler.
func DomainForward(hostname, addr string, clients ...*fasthttp.Client) fiber.Handler {
	base, err := validateUpstream(addr, currentSecurityPolicy())
	if err != nil {
		panic(err)
	}
	return func(c fiber.Ctx) error {
		// Host names are case-insensitive (RFC 9110 §4.2.3) and fasthttp
		// does not case-fold the raw Host header, so compare with
		// EqualFold — otherwise "API.Example.com" would slip past a
		// DomainForward("api.example.com", ...) gate and be passed
		// through unproxied.
		host := utils.UnsafeString(c.Request().Host())
		if !utils.EqualFold(host, hostname) {
			return nil
		}
		c.Request().Header.Set("X-Real-IP", c.IP())
		return doActionWithPolicy(c, joinUpstreamPath(base, c.OriginalURL()), currentSecurityPolicy(),
			func(cli *fasthttp.Client, req *fasthttp.Request, resp *fasthttp.Response, _ *url.URL) error {
				return cli.Do(req, resp)
			}, clients...)
	}
}

// urlRoundrobin is the *url.URL-typed equivalent of the legacy
// string-based round-robin. Storing parsed URLs lets BalancerForward
// skip per-request url.Parse on its configured upstream list.
type urlRoundrobin struct {
	pool []*url.URL

	current int
	sync.Mutex
}

func (r *urlRoundrobin) get() *url.URL {
	r.Lock()
	defer r.Unlock()

	if r.current >= len(r.pool) {
		r.current %= len(r.pool)
	}

	result := r.pool[r.current]
	r.current++
	return result
}

// BalancerForward Forward performs the given http request with round robin algorithm to server and fills the given http response.
// This method will return a fiber.Handler.
//
// As with DomainForward, every server is parsed and policy-checked at
// handler construction. A misconfigured entry panics at startup.
//
// SSRF note: despite the name, this helper dispatches through the
// shared/user-supplied client rather than a Balancer HostClient, but it
// gets the same protection as Do — up-front host validation plus the
// dial-time validated-IP guard on the dispatching client when
// AllowPrivateIPs is false.
func BalancerForward(servers []string, clients ...*fasthttp.Client) fiber.Handler {
	if len(servers) == 0 {
		panic("Servers cannot be empty")
	}
	policy := currentSecurityPolicy()
	bases := make([]*url.URL, len(servers))
	for i, s := range servers {
		base, err := validateUpstream(s, policy)
		if err != nil {
			panic(err)
		}
		bases[i] = base
	}
	r := &urlRoundrobin{pool: bases}
	return func(c fiber.Ctx) error {
		base := r.get()
		c.Request().Header.Set("X-Real-IP", c.IP())
		return doActionWithPolicy(c, joinUpstreamPath(base, c.OriginalURL()), currentSecurityPolicy(),
			func(cli *fasthttp.Client, req *fasthttp.Request, resp *fasthttp.Response, _ *url.URL) error {
				return cli.Do(req, resp)
			}, clients...)
	}
}

package fiber

import (
	"bytes"
	"errors"
	"math"
	"mime/multipart"
	"net"
	"strings"
	"time"

	"github.com/gofiber/utils/v2"
	utilsbytes "github.com/gofiber/utils/v2/bytes"
	utilsstrings "github.com/gofiber/utils/v2/strings"
	"github.com/valyala/bytebufferpool"
	"github.com/valyala/fasthttp"
	"golang.org/x/net/idna"
)

// Pre-allocated byte slices for common header comparisons to avoid allocations
var (
	xForwardedPrefix        = []byte("X-Forwarded-")
	xForwardedProtoBytes    = []byte(HeaderXForwardedProto)
	xForwardedProtocolBytes = []byte(HeaderXForwardedProtocol)
	xForwardedSslBytes      = []byte(HeaderXForwardedSsl)
	xURLSchemeBytes         = []byte(HeaderXUrlScheme)
	onBytes                 = []byte("on")
)

// Range represents the parsed HTTP Range header extracted by DefaultReq.Range.
type Range struct {
	Type   string
	Ranges []RangeSet
}

// RangeSet represents a single content range from a request.
type RangeSet struct {
	Start int64
	End   int64
}

// DefaultReq is the default implementation of Req used by DefaultCtx.
//
//go:generate ifacemaker --file req.go --struct DefaultReq --iface Req --pkg fiber --output req_interface_gen.go --not-exported true --iface-comment "Req is an interface for request-related Ctx methods."
type DefaultReq struct {
	c *DefaultCtx
}

// Accepts checks if the specified extensions or content types are acceptable.
func (r *DefaultReq) Accepts(offers ...string) string {
	header := joinHeaderValues(r.c.fasthttp.Request.Header.PeekAll(HeaderAccept))
	return getOffer(header, acceptsOfferType, offers...)
}

// AcceptsCharsets checks if the specified charset is acceptable.
func (r *DefaultReq) AcceptsCharsets(offers ...string) string {
	header := joinHeaderValues(r.c.fasthttp.Request.Header.PeekAll(HeaderAcceptCharset))
	return getOffer(header, acceptsOffer, offers...)
}

// AcceptsEncodings checks if the specified encoding is acceptable.
func (r *DefaultReq) AcceptsEncodings(offers ...string) string {
	header := joinHeaderValues(r.c.fasthttp.Request.Header.PeekAll(HeaderAcceptEncoding))
	return getOffer(header, acceptsOffer, offers...)
}

// AcceptsLanguages checks if the specified language is acceptable using
// RFC 4647 Basic Filtering.
func (r *DefaultReq) AcceptsLanguages(offers ...string) string {
	header := joinHeaderValues(r.c.fasthttp.Request.Header.PeekAll(HeaderAcceptLanguage))
	return getOffer(header, acceptsLanguageOfferBasic, offers...)
}

// AcceptsLanguagesExtended checks if the specified language is acceptable using
// RFC 4647 Extended Filtering.
func (r *DefaultReq) AcceptsLanguagesExtended(offers ...string) string {
	header := joinHeaderValues(r.c.fasthttp.Request.Header.PeekAll(HeaderAcceptLanguage))
	return getOffer(header, acceptsLanguageOfferExtended, offers...)
}

// App returns the *App reference to the instance of the Fiber application
func (r *DefaultReq) App() *App {
	return r.c.app
}

// BaseURL returns (protocol + host + base path).
func (r *DefaultReq) BaseURL() string {
	return r.c.BaseURL()
}

// BodyRaw contains the raw body submitted in a POST request.
// Returned value is only valid within the handler. Do not store any references.
// Make copies or use the Immutable setting instead.
func (r *DefaultReq) BodyRaw() []byte {
	return r.getBody()
}

//nolint:nonamedreturns // gocritic unnamedResult prefers naming decoded body, decode count, and error
func (r *DefaultReq) tryDecodeBodyInOrder(
	originalBody *[]byte,
	encodings []string,
) (body []byte, decodesRealized uint8, err error) {
	request := &r.c.fasthttp.Request
	maxBodySize := r.c.app.config.BodyLimit
	for idx := range encodings {
		i := len(encodings) - 1 - idx
		encoding := encodings[i]
		decodesRealized++
		var decodeErr error
		switch encoding {
		case StrGzip, "x-gzip":
			body, decodeErr = request.BodyGunzipWithLimit(maxBodySize)
		case StrBr, StrBrotli:
			body, decodeErr = request.BodyUnbrotliWithLimit(maxBodySize)
		case StrDeflate:
			body, decodeErr = request.BodyInflateWithLimit(maxBodySize)
		case StrZstd:
			body, decodeErr = request.BodyUnzstdWithLimit(maxBodySize)
		case StrIdentity:
			body = request.Body()
		case StrCompress, "x-compress":
			return nil, decodesRealized - 1, ErrNotImplemented
		default:
			return nil, decodesRealized - 1, ErrUnsupportedMediaType
		}

		if decodeErr != nil {
			return nil, decodesRealized, decodeErr
		}

		if i > 0 && decodesRealized > 0 {
			if i == len(encodings)-1 {
				tempBody := request.Body()
				*originalBody = make([]byte, len(tempBody))
				copy(*originalBody, tempBody)
			}
			request.SetBodyRaw(body)
		}
	}

	return body, decodesRealized, nil
}

// Body contains the raw body submitted in a POST request.
// This method will decompress the body if the 'Content-Encoding' header is provided.
// It returns the original (or decompressed) body data which is valid only within the handler.
// Don't store direct references to the returned data.
// If you need to keep the body's data later, make a copy or use the Immutable option.
func (r *DefaultReq) Body() []byte {
	var (
		err                error
		body, originalBody []byte
		headerEncoding     string
		encodingOrder      = []string{"", "", ""}
	)

	request := &r.c.fasthttp.Request

	// Fast path: no Content-Encoding header at all. ContentEncoding uses the
	// pre-normalized key constant, so absence costs a single cheap lookup.
	// An empty value is still a present field line and must be joined with
	// duplicates below before RFC 9110 empty-list elements are ignored.
	if request.Header.ContentEncoding() == nil {
		return r.getBody()
	}

	// Get Content-Encoding header. Multiple field lines form one combined
	// list (RFC 9110 Section 5.2), so join them before splitting.
	encodedBytes, _ := peekJoinedRequestHeader(&request.Header, HeaderContentEncoding)
	headerEncoding = utils.UnsafeString(utilsbytes.UnsafeToLower(encodedBytes))

	// Split and get the encodings list, in order to attend the
	// rule defined at: https://www.rfc-editor.org/rfc/rfc9110#section-8.4-5
	// The splitter drops empty list elements (RFC 9110 Section 5.6.1.2), and
	// headerEncoding was already lowercased wholesale above.
	encodingOrder = getSplicedStrList(headerEncoding, encodingOrder)
	if len(encodingOrder) == 0 {
		return r.getBody()
	}

	var decodesRealized uint8
	body, decodesRealized, err = r.tryDecodeBodyInOrder(&originalBody, encodingOrder)

	// Ensure that the body will be the original
	if originalBody != nil && decodesRealized > 0 {
		request.SetBodyRaw(originalBody)
	}
	if err != nil {
		switch {
		case errors.Is(err, ErrUnsupportedMediaType):
			_ = r.c.DefaultRes.SendStatus(StatusUnsupportedMediaType) //nolint:errcheck,staticcheck // It is fine to ignore the error and the static check
		case errors.Is(err, ErrNotImplemented):
			_ = r.c.DefaultRes.SendStatus(StatusNotImplemented) //nolint:errcheck,staticcheck // It is fine to ignore the error and the static check
		case errors.Is(err, fasthttp.ErrBodyTooLarge):
			_ = r.c.DefaultRes.SendStatus(StatusRequestEntityTooLarge) //nolint:errcheck,staticcheck // It is fine to ignore the error and the static check
		default:
			// do nothing
		}
		return []byte(err.Error())
	}

	return r.c.app.GetBytes(body)
}

// RequestCtx returns *fasthttp.RequestCtx that carries a deadline
// a cancellation signal, and other values across API boundaries.
func (r *DefaultReq) RequestCtx() *fasthttp.RequestCtx {
	return r.c.fasthttp
}

// FullURL returns the full request URL (protocol + host + original URL).
func (c *DefaultCtx) FullURL() string {
	buf := bytebufferpool.Get()
	defer bytebufferpool.Put(buf)

	buf.WriteString(c.Scheme())
	buf.WriteString("://")
	buf.WriteString(c.Host())
	buf.WriteString(c.OriginalURL())

	return buf.String()
}

// UserAgent returns the User-Agent request header.
func (c *DefaultCtx) UserAgent() string {
	return c.app.toString(c.fasthttp.Request.Header.UserAgent())
}

// Referer returns the Referer request header.
func (c *DefaultCtx) Referer() string {
	return c.app.toString(c.fasthttp.Request.Header.Referer())
}

// AcceptLanguage returns the Accept-Language request header.
// Repeated field lines are combined into one comma-joined list
// (RFC 9110 Section 5.2), matching what AcceptsLanguages negotiates on.
func (c *DefaultCtx) AcceptLanguage() string {
	return c.app.toString(joinHeaderValues(c.fasthttp.Request.Header.PeekAll(HeaderAcceptLanguage)))
}

// AcceptEncoding returns the Accept-Encoding request header.
// Repeated field lines are combined into one comma-joined list
// (RFC 9110 Section 5.2), matching what AcceptsEncodings negotiates on.
func (c *DefaultCtx) AcceptEncoding() string {
	return c.app.toString(joinHeaderValues(c.fasthttp.Request.Header.PeekAll(HeaderAcceptEncoding)))
}

// HasHeader reports whether the request includes a header with the given key.
func (c *DefaultCtx) HasHeader(key string) bool {
	return len(c.fasthttp.Request.Header.Peek(key)) > 0
}

// MediaType returns the MIME type from the Content-Type header without parameters.
func (c *DefaultCtx) MediaType() string {
	contentType := utils.TrimSpace(c.fasthttp.Request.Header.ContentType())
	if len(contentType) == 0 {
		return ""
	}
	if idx := bytes.IndexByte(contentType, ';'); idx != -1 {
		contentType = contentType[:idx]
	}
	contentType = utils.TrimSpace(contentType)
	return c.app.toString(contentType)
}

// Charset returns the charset parameter from the Content-Type header.
func (c *DefaultCtx) Charset() string {
	contentType := c.fasthttp.Request.Header.ContentType()
	_, params, ok := bytes.Cut(contentType, []byte{';'})
	if !ok {
		return ""
	}
	for len(params) > 0 {
		// Slice off the next parameter at the next ";" that sits outside a
		// quoted-string: parameter values may be quoted and contain ";"
		// (RFC 9110 Section 5.6.6). A DQUOTE only opens a quoted-string at
		// the start of a value (after an "=" plus optional whitespace), so a
		// stray quote later in an unquoted value cannot swallow the rest of
		// the header.
		param := params
		end := -1
		inQuotes := false
		escaped := false
		expectValue := false
	scan:
		for i := 0; i < len(params); i++ {
			ch := params[i]
			switch {
			case escaped:
				escaped = false
			case inQuotes:
				switch ch {
				case '\\':
					escaped = true
				case '"':
					inQuotes = false
				}
			case ch == '=':
				expectValue = true
			case ch == '"' && expectValue:
				inQuotes = true
				expectValue = false
			case ch == ';':
				end = i
				break scan
			case ch != ' ' && ch != '\t':
				expectValue = false
			}
		}
		if end >= 0 {
			param = params[:end]
			params = params[end+1:]
		} else {
			params = nil
		}

		name, value, ok := bytes.Cut(param, []byte{'='})
		if !ok || !utils.EqualFold(utils.TrimSpace(name), []byte("charset")) {
			continue
		}
		v := utils.TrimSpace(value)
		if len(v) > 0 && v[0] == '"' {
			// A quoted value must be a complete quoted-string, and its
			// quoted-pairs must be replaced with the escaped octet
			// (RFC 9110 Section 5.6.4).
			if len(v) < 2 || v[len(v)-1] != '"' {
				return ""
			}
			unescaped, err := unescapeHeaderValue(v[1 : len(v)-1])
			if err != nil {
				return ""
			}
			v = unescaped
		} else if bytes.IndexByte(v, '"') >= 0 {
			// A bare token must not contain DQUOTE; skip the invalid
			// parameter instead of surfacing garbage, so a well-formed
			// charset parameter later in the header can still be found.
			continue
		}
		return c.app.toString(v)
	}
	return ""
}

// IsJSON reports whether the Content-Type header is JSON.
func (c *DefaultCtx) IsJSON() bool {
	return utils.EqualFold(c.MediaType(), MIMEApplicationJSON)
}

// IsForm reports whether the Content-Type header is form-encoded.
func (c *DefaultCtx) IsForm() bool {
	return utils.EqualFold(c.MediaType(), MIMEApplicationForm)
}

// IsMultipart reports whether the Content-Type header is multipart form data.
func (c *DefaultCtx) IsMultipart() bool {
	return utils.EqualFold(c.MediaType(), MIMEMultipartForm)
}

// AcceptsJSON reports whether the Accept header allows JSON.
func (c *DefaultCtx) AcceptsJSON() bool {
	return c.Accepts(MIMEApplicationJSON) != ""
}

// AcceptsHTML reports whether the Accept header allows HTML.
func (c *DefaultCtx) AcceptsHTML() bool {
	return c.Accepts(MIMETextHTML) != ""
}

// AcceptsXML reports whether the Accept header allows XML.
func (c *DefaultCtx) AcceptsXML() bool {
	return c.Accepts(MIMEApplicationXML, MIMETextXML) != ""
}

// AcceptsEventStream reports whether the Accept header allows text/event-stream.
func (c *DefaultCtx) AcceptsEventStream() bool {
	return c.Accepts(MIMETextEventStream) != ""
}

// Cookies are used for getting a cookie value by key.
// Defaults to the empty string "" if the cookie doesn't exist.
// If a default value is given, it will return that value if the cookie doesn't exist.
// The returned value is only valid within the handler. Do not store any references.
// Make copies or use the Immutable setting to use the value outside the Handler.
func (r *DefaultReq) Cookies(key string, defaultValue ...string) string {
	return defaultString(r.c.app.toString(r.c.fasthttp.Request.Header.Cookie(key)), defaultValue)
}

// Request return the *fasthttp.Request object
// This allows you to use all fasthttp request methods
// https://godoc.org/github.com/valyala/fasthttp#Request
func (r *DefaultReq) Request() *fasthttp.Request {
	return &r.c.fasthttp.Request
}

// FormFile returns the first file by key from a MultipartForm.
// The multipart form is parsed using the application's BodyLimit to prevent
// unbounded memory usage.
func (r *DefaultReq) FormFile(key string) (*multipart.FileHeader, error) {
	if _, err := r.MultipartForm(); err != nil {
		return nil, err
	}
	return r.c.fasthttp.FormFile(key)
}

// FormValue returns the first value by key from a MultipartForm.
// Search is performed in QueryArgs, PostArgs, MultipartForm and FormFile in this particular order.
// Defaults to the empty string "" if the form value doesn't exist.
// If a default value is given, it will return that value if the form value does not exist.
// Returned value is only valid within the handler. Do not store any references.
// Make copies or use the Immutable setting instead.
// When the request is a multipart form, it is parsed using the application's
// BodyLimit so the configured limit is consistently enforced.
func (r *DefaultReq) FormValue(key string, defaultValue ...string) string {
	if r.c.IsMultipart() {
		// For multipart requests, parse the form using the application's BodyLimit.
		// fasthttp's FormValue would otherwise re-parse with its default 8 MiB limit,
		// effectively bypassing the configured BodyLimit.
		//
		// Preserve the original search order: QueryArgs → PostArgs → MultipartForm.
		if v := r.c.fasthttp.QueryArgs().Peek(key); len(v) > 0 {
			return r.c.app.toString(v)
		}
		if v := r.c.fasthttp.PostArgs().Peek(key); len(v) > 0 {
			return r.c.app.toString(v)
		}
		mf, err := r.MultipartForm()
		if err != nil {
			return defaultString("", defaultValue)
		}
		if vals := mf.Value[key]; len(vals) > 0 {
			return vals[0]
		}
		return defaultString("", defaultValue)
	}
	return defaultString(r.c.app.toString(r.c.fasthttp.FormValue(key)), defaultValue)
}

// Fresh returns true when the response is still “fresh” in the client's cache,
// otherwise false is returned to indicate that the client cache is now stale
// and the full response should be sent.
// Freshness only applies to GET and HEAD requests; for any other method false is
// returned, as RFC 9110 defines 304 Not Modified only for those methods and
// requires If-Modified-Since to be ignored otherwise.
// When a client sends the Cache-Control: no-cache request header to indicate an end-to-end
// reload request, this module will return false to make handling these requests transparent.
// https://github.com/jshttp/fresh/blob/master/index.js#L33
func (r *DefaultReq) Fresh() bool {
	// Freshness only applies to GET and HEAD requests: a 304 Not Modified
	// response is defined for those methods only, and RFC 9110 Section 13.1.3
	// requires If-Modified-Since to be ignored for any other method.
	// A negative methodInt means the method is not registered at all, so it
	// cannot be GET or HEAD (and must not be used to index RequestMethods).
	if r.c.methodInt < 0 {
		return false
	}
	if method := r.c.app.method(r.c.methodInt); method != MethodGet && method != MethodHead {
		return false
	}

	header := &r.c.fasthttp.Request.Header

	// fields
	// List-based fields may be split across multiple field lines, which are
	// semantically one comma-joined list (RFC 9110 Section 5.2).
	modifiedSince := header.Peek(HeaderIfModifiedSince)
	noneMatch := joinHeaderValues(header.PeekAll(HeaderIfNoneMatch))

	// unconditional request
	if len(modifiedSince) == 0 && len(noneMatch) == 0 {
		return false
	}

	// Always return stale when Cache-Control: no-cache
	// to support end-to-end reload requests
	// https://www.rfc-editor.org/rfc/rfc9111#section-5.2.1.4
	cacheControl := joinHeaderValues(header.PeekAll(HeaderCacheControl))
	if len(cacheControl) > 0 && isNoCache(utils.UnsafeString(cacheControl)) {
		return false
	}

	// if-none-match takes precedence over if-modified-since (RFC 9110)
	if len(noneMatch) > 0 {
		if len(noneMatch) == 1 && noneMatch[0] == '*' {
			return true
		}
		app := r.c.app
		response := &r.c.fasthttp.Response
		etag := app.toString(response.Header.Peek(HeaderETag))
		if etag == "" {
			return false
		}
		if app.isEtagStale(etag, noneMatch) {
			return false
		}
		return true
	}

	// if-modified-since (only reached when if-none-match is absent)
	if len(modifiedSince) > 0 {
		response := &r.c.fasthttp.Response
		lastModified := response.Header.Peek(HeaderLastModified)
		if len(lastModified) == 0 {
			return false
		}
		lastModifiedTime, err := parseHTTPDate(lastModified)
		if err != nil {
			return false
		}
		// Common conditional request: the client echoes back the exact
		// Last-Modified it was given. Identical, already-validated dates are
		// equal, so skip the second parse and comparison.
		if !bytes.Equal(lastModified, modifiedSince) {
			modifiedSinceTime, err := parseHTTPDate(modifiedSince)
			if err != nil {
				return false
			}
			if lastModifiedTime.Compare(modifiedSinceTime) == 1 {
				return false
			}
		}
	}
	return true
}

// parseHTTPDate parses an HTTP-date field value. RFC 9110 Section 5.6.7
// requires recipients to accept the obsolete RFC 850 and ANSI C asctime()
// formats in addition to the preferred IMF-fixdate; utils.ParseHTTPDate
// covers all three with net/http.ParseTime semantics, taking an
// allocation-free fast path for canonical IMF-fixdate input. Unlike
// net/http.ParseTime it also tolerates surrounding ASCII whitespace —
// deliberate here, matching RFC 9110 §5.5's exclusion of leading and
// trailing OWS from field values.
func parseHTTPDate(date []byte) (time.Time, error) {
	t, err := utils.ParseHTTPDate(date)
	if err != nil {
		// Callers only nil-check the error; skip wrapping to avoid an
		// allocation for every malformed client-supplied date.
		return time.Time{}, err //nolint:wrapcheck // see above
	}
	return t, nil
}

// Get returns the HTTP request header specified by field.
// Field names are case-insensitive
// Returned value is only valid within the handler. Do not store any references.
// Make copies or use the Immutable setting instead.
func (r *DefaultReq) Get(key string, defaultValue ...string) string {
	return GetReqHeader(r.c, key, defaultValue...)
}

// GetReqHeader returns the HTTP request header specified by filed.
// This function is generic and can handle different headers type values.
// If the generic type cannot be matched to a supported type, the function
// returns the default value (if provided) or the zero value of type V.
func GetReqHeader[V GenericType](c Ctx, key string, defaultValue ...V) V {
	v, err := genericParseType[V](c.App().toString(c.Request().Header.Peek(key)))
	if err != nil && len(defaultValue) > 0 {
		return defaultValue[0]
	}
	return v
}

// GetHeaders (a.k.a GetReqHeaders) returns the HTTP request headers.
// Returned value is only valid within the handler. Do not store any references.
// Make copies or use the Immutable setting instead.
func (r *DefaultReq) GetHeaders() map[string][]string {
	app := r.c.app
	reqHeader := &r.c.fasthttp.Request.Header
	// Pre-allocate map with known header count to avoid reallocations
	headers := make(map[string][]string, reqHeader.Len())
	for k, v := range reqHeader.All() {
		key := app.toString(k)
		headers[key] = append(headers[key], app.toString(v))
	}
	return headers
}

// Host contains the host derived from the X-Forwarded-Host or Host HTTP header.
// Returned value is only valid within the handler. Do not store any references.
// In a network context, `Host` refers to the combination of a hostname and potentially a port number used for connecting,
// while `Hostname` refers specifically to the name assigned to a device on a network, excluding any port information.
// Example: URL: https://example.com:8080 -> Host: example.com:8080
// Make copies or use the Immutable setting instead.
// Please use Config.TrustProxy to prevent header spoofing if your app is behind a proxy.
func (r *DefaultReq) Host() string {
	if r.IsProxyTrusted() {
		if host := r.Get(HeaderXForwardedHost); host != "" {
			if before, _, found := strings.Cut(host, ","); found {
				return utils.TrimSpace(before)
			}
			return utils.TrimSpace(host)
		}
	}
	return r.c.app.toString(r.c.fasthttp.Request.URI().Host())
}

// Hostname contains the hostname derived from the X-Forwarded-Host or Host HTTP header using the c.Host() method.
// Returned value is only valid within the handler. Do not store any references.
// Example: URL: https://example.com:8080 -> Hostname: example.com
// Make copies or use the Immutable setting instead.
// Please use Config.TrustProxy to prevent header spoofing if your app is behind a proxy.
func (r *DefaultReq) Hostname() string {
	addr, _ := parseAddr(r.Host())

	return addr
}

// Port returns the remote port of the request.
func (r *DefaultReq) Port() string {
	addr := r.c.fasthttp.RemoteAddr()
	if addr == nil {
		return "0"
	}
	switch typedAddr := addr.(type) {
	case *net.TCPAddr:
		return utils.FormatInt(int64(typedAddr.Port))
	case *net.UnixAddr:
		return ""
	}

	_, port, err := net.SplitHostPort(addr.String())
	if err != nil {
		return ""
	}

	return port
}

// IP returns the client's IP address. When the request comes from a trusted proxy (see
// [TrustProxyConfig]), the value is extracted from the configured ProxyHeader by walking the
// X-Forwarded-For chain right-to-left and skipping all trusted proxy IPs; the first
// non-trusted IP in the chain is returned. Please use Config.TrustProxy to prevent header
// spoofing if your app is behind a proxy.
func (r *DefaultReq) IP() string {
	app := r.c.app
	if r.IsProxyTrusted() && app.config.ProxyHeader != "" {
		return r.extractIPFromHeader(app.config.ProxyHeader)
	}

	if ip := r.c.fasthttp.RemoteIP(); ip != nil {
		return ip.String()
	}
	return ""
}

// extractIPsFromHeader will return a slice of IPs it found given a header name in the order they appear.
// When IP validation is enabled, any invalid IPs will be omitted.
func (r *DefaultReq) extractIPsFromHeader(header string) []string {
	// TODO: Reuse the c.extractIPFromHeader func somehow in here

	headerValue := r.Get(header)

	// We can't know how many IPs we will return, but we will try to guess with this constant division.
	// Counting ',' makes function slower for about 50ns in general case.
	const maxEstimatedCount = 8
	estimatedCount := min(len(headerValue)/maxEstimatedCount,
		// Avoid big allocation on big header
		maxEstimatedCount)

	ipsFound := make([]string, 0, estimatedCount)

	i := 0
	j := -1

	for {
		var v4, v6 bool

		// Manually splitting string without allocating slice, working with parts directly
		i, j = j+1, j+2

		if j > len(headerValue) {
			break
		}

		for j < len(headerValue) && headerValue[j] != ',' {
			switch headerValue[j] {
			case ':':
				v6 = true
			case '.':
				v4 = true
			default:
				// do nothing
			}
			j++
		}

		for i < j && (headerValue[i] == ' ' || headerValue[i] == ',') {
			i++
		}

		s := utils.TrimRight(headerValue[i:j], ' ')

		if r.c.app.config.EnableIPValidation {
			// Skip validation if IP is clearly not IPv4/IPv6; otherwise, validate without allocations
			if (!v6 && !v4) || (v6 && !utils.IsIPv6(s)) || (v4 && !utils.IsIPv4(s)) {
				continue
			}
		}

		ipsFound = append(ipsFound, s)
	}

	return ipsFound
}

// extractIPFromHeader returns the client IP from the given proxy header by walking the
// X-Forwarded-For chain from right to left and stripping trusted proxy IPs. When trusted
// proxies are configured, the rightmost non-trusted IP is returned; otherwise the first
// valid IP (left-to-right) is returned. When IP validation is disabled, the raw header
// value is returned as-is.
func (r *DefaultReq) extractIPFromHeader(header string) string {
	app := r.c.app

	if !app.config.EnableIPValidation {
		return r.Get(header)
	}

	headerValue := r.Get(header)
	hasTrustedProxyConfig := r.hasTrustedProxyConfig()
	if !hasTrustedProxyConfig {
		start := 0
		for {
			end := start
			for end < len(headerValue) && headerValue[end] != ',' {
				end++
			}

			ipStr := utils.Trim(headerValue[start:end], ' ')
			if isValidProxyIP(ipStr) {
				return ipStr
			}
			if end == len(headerValue) {
				break
			}
			start = end + 1
		}
	}

	var leftmostIP string

	for end := len(headerValue); end > 0; {
		start := end
		for start > 0 && headerValue[start-1] != ',' {
			start--
		}

		ipStr := utils.Trim(headerValue[start:end], ' ')
		if isValidProxyIP(ipStr) {
			leftmostIP = ipStr
			if !r.isTrustedProxyIP(ipStr) {
				return ipStr
			}
		}

		if start == 0 {
			break
		}
		end = start - 1
	}

	if leftmostIP != "" {
		return leftmostIP
	}
	if ip := r.c.fasthttp.RemoteIP(); ip != nil {
		return ip.String()
	}
	return ""
}

func isValidProxyIP(ipStr string) bool {
	hasIPv4Separator := strings.IndexByte(ipStr, '.') >= 0
	hasIPv6Separator := strings.IndexByte(ipStr, ':') >= 0
	return (hasIPv4Separator || hasIPv6Separator) &&
		(!hasIPv4Separator || utils.IsIPv4(ipStr)) &&
		(!hasIPv6Separator || utils.IsIPv6(ipStr))
}

// hasTrustedProxyConfig returns true if any trusted proxy configuration is set.
func (r *DefaultReq) hasTrustedProxyConfig() bool {
	cfg := r.c.app.config.TrustProxyConfig
	return len(cfg.ips) > 0 || len(cfg.ranges) > 0 || cfg.Loopback || cfg.Private || cfg.LinkLocal
}

// isTrustedProxyIP checks whether the given IP string matches any configured trusted proxy.
func (r *DefaultReq) isTrustedProxyIP(ipStr string) bool {
	cfg := r.c.app.config.TrustProxyConfig

	// utils.ParseIPv4/ParseIPv6 together accept exactly the strings
	// netip.ParseAddr does, without allocating an error for invalid input.
	ip, ok := utils.ParseIPv4(ipStr)
	if !ok {
		if ip, ok = utils.ParseIPv6(ipStr); !ok {
			return false
		}
	}

	if cfg.Loopback && ip.IsLoopback() {
		return true
	}
	if cfg.Private && ip.IsPrivate() {
		return true
	}
	if cfg.LinkLocal && ip.IsLinkLocalUnicast() {
		return true
	}

	var canonicalIP [net.IPv6len * 3]byte
	if _, trusted := cfg.ips[utils.UnsafeString(ip.AppendTo(canonicalIP[:0]))]; trusted {
		return true
	}
	if len(cfg.ranges) == 0 {
		return false
	}

	if ip.Is4() {
		ipv4 := ip.As4()
		for _, ipNet := range cfg.ranges {
			if ipNet.Contains(ipv4[:]) {
				return true
			}
		}
		return false
	}

	ipv6 := ip.As16()
	for _, ipNet := range cfg.ranges {
		if ipNet.Contains(ipv6[:]) {
			return true
		}
	}
	return false
}

// IPs returns a string slice of IP addresses specified in the X-Forwarded-For request header.
// When IP validation is enabled, only valid IPs are returned.
func (r *DefaultReq) IPs() []string {
	return r.extractIPsFromHeader(HeaderXForwardedFor)
}

// Is returns the matching content type,
// if the incoming request's Content-Type HTTP header field matches the MIME type specified by the type parameter
func (r *DefaultReq) Is(extension string) bool {
	extensionHeader := utils.GetMIME(extension)
	if extensionHeader == "" {
		return false
	}

	ct := r.c.app.toString(r.c.fasthttp.Request.Header.ContentType())
	if i := strings.IndexByte(ct, ';'); i != -1 {
		ct = ct[:i]
	}
	ct = utils.TrimSpace(ct)
	return utils.EqualFold(ct, extensionHeader)
}

// Locals makes it possible to pass any values under keys scoped to the request
// and therefore available to all following routes that match the request.
//
// All the values are removed from ctx after returning from the top
// RequestHandler. Additionally, Close method is called on each value
// implementing io.Closer before removing the value from ctx.
func (r *DefaultReq) Locals(key any, value ...any) any {
	if r.c.fasthttp == nil {
		if len(value) > 0 {
			return value[0]
		}
		return nil
	}
	if len(value) == 0 {
		return r.c.fasthttp.UserValue(key)
	}
	r.c.fasthttp.SetUserValue(key, value[0])
	return value[0]
}

// Locals function utilizing Go's generics feature.
// This function allows for manipulating and retrieving local values within a
// request context with a more specific data type.
//
// All the values are removed from ctx after returning from the top
// RequestHandler. Additionally, Close method is called on each value
// implementing io.Closer before removing the value from ctx.
func Locals[V any](c Ctx, key any, value ...V) V {
	var v V
	var ok bool
	if len(value) == 0 {
		v, ok = c.Locals(key).(V)
	} else {
		v, ok = c.Locals(key, value[0]).(V)
	}
	if !ok {
		return v // return zero of type V
	}
	return v
}

// Method returns the HTTP request method for the context, optionally overridden by the provided argument.
// If no override is given or if the provided override is not a valid HTTP method, it returns the current method from the context.
// Otherwise, it updates the context's method and returns the overridden method as a string.
func (r *DefaultReq) Method(override ...string) string {
	app := r.c.app
	if len(override) == 0 {
		// Nothing to override, just return current method from context
		return currentMethod(r.c)
	}

	// Method tokens are case-sensitive (RFC 9110 Section 9.1), so try the
	// override exactly as given first — this is what keeps mixed-case custom
	// methods registered via Config.RequestMethods working.
	method := override[0]
	methodInt := app.methodInt(method)
	if methodInt == -1 {
		// Fall back to the conventional uppercase form as a convenience for
		// the standard methods (e.g. "get" -> "GET").
		method = utilsstrings.ToUpper(method)
		methodInt = app.methodInt(method)
	}
	if methodInt == -1 {
		// Provided override is not a registered HTTP method; no override,
		// return current method
		return currentMethod(r.c)
	}
	r.c.methodInt = methodInt
	// Method changed; invalidate the lookahead index
	r.c.firstMatchIndex = -1
	return method
}

// currentMethod resolves the context's method, falling back to the raw
// request header value when the method is not registered in RequestMethods,
// so unregistered methods are reported instead of panicking.
// It is a package-level function (not a method) to stay off the generated
// Req/Ctx interfaces.
func currentMethod(c *DefaultCtx) string {
	// app.method owns the definition of "unregistered" (it bounds-checks
	// methodInt and returns "" for anything out of range).
	if m := c.app.method(c.methodInt); m != "" {
		return m
	}
	// Copy the raw header bytes: every other return path yields a stable
	// string from RequestMethods, so callers may retain the result beyond
	// the handler; an unsafe alias into the request buffer would be
	// silently corrupted on connection reuse.
	return string(c.fasthttp.Request.Header.Method())
}

// MultipartForm parse form entries from binary.
// This returns a map[string][]string, so given a key, the value will be a string slice.
func (r *DefaultReq) MultipartForm() (*multipart.Form, error) {
	return r.c.fasthttp.MultipartFormWithLimit(r.c.app.config.BodyLimit)
}

// OriginalURL contains the original request URL.
// Returned value is only valid within the handler. Do not store any references.
// Make copies or use the Immutable setting to use the value outside the Handler.
func (r *DefaultReq) OriginalURL() string {
	return r.c.app.toString(r.c.fasthttp.Request.Header.RequestURI())
}

// Params is used to get the route parameters.
// Defaults to empty string "" if the param doesn't exist.
// If a default value is given, it will return that value if the param doesn't exist.
// Returned value is only valid within the handler. Do not store any references.
// Make copies or use the Immutable setting to use the value outside the Handler.
func (r *DefaultReq) Params(key string, defaultValue ...string) string {
	if key == "*" || key == "+" {
		key += "1"
	}

	app := r.c.app
	route := r.c.Route()
	values := &r.c.values
	for i := range route.Params {
		if len(key) != len(route.Params[i]) {
			continue
		}
		if route.Params[i] == key || (!app.config.CaseSensitive && utils.EqualFold(route.Params[i], key)) {
			// if there is no value for the key
			if len(values) <= i || values[i] == "" {
				break
			}
			val := values[i]
			return r.c.app.GetString(val)
		}
	}
	return defaultString("", defaultValue)
}

// Params is used to get the route parameters.
// This function is generic and can handle different route parameters type values.
// If the generic type cannot be matched to a supported type, the function
// returns the default value (if provided) or the zero value of type V.
//
// Example:
//
// http://example.com/user/:user -> http://example.com/user/john
// Params[string](c, "user") -> returns john
//
// http://example.com/id/:id -> http://example.com/user/114
// Params[int](c, "id") ->  returns 114 as integer.
//
// http://example.com/id/:number -> http://example.com/id/john
// Params[int](c, "number", 0) -> returns 0 because can't parse 'john' as integer.
func Params[V GenericType](c Ctx, key string, defaultValue ...V) V {
	v, err := genericParseType[V](c.Params(key))
	if err != nil && len(defaultValue) > 0 {
		return defaultValue[0]
	}
	return v
}

// Scheme contains the request protocol string: http or https for TLS requests.
// Please use Config.TrustProxy to prevent header spoofing if your app is behind a proxy.
func (r *DefaultReq) Scheme() string {
	ctx := r.c.fasthttp
	if ctx.IsTLS() {
		return schemeHTTPS
	}
	if !r.IsProxyTrusted() {
		return schemeHTTP
	}

	app := r.c.app
	scheme := schemeHTTP
	const lenXHeaderName = 12
	for key, val := range ctx.Request.Header.All() {
		if len(key) < lenXHeaderName {
			continue // Neither "X-Forwarded-" nor "X-Url-Scheme"
		}
		switch {
		case utils.EqualFold(key[:len(xForwardedPrefix)], xForwardedPrefix):
			if utils.EqualFold(key, xForwardedProtoBytes) ||
				utils.EqualFold(key, xForwardedProtocolBytes) {
				v := app.toString(val)
				if before, _, found := strings.Cut(v, ","); found {
					scheme = utils.TrimSpace(before)
				} else {
					scheme = utils.TrimSpace(v)
				}
			} else if utils.EqualFold(key, xForwardedSslBytes) && utils.EqualFold(val, onBytes) {
				scheme = schemeHTTPS
			}

		case utils.EqualFold(key, xURLSchemeBytes):
			scheme = utils.TrimSpace(app.toString(val))
		default:
			continue
		}
	}
	return utilsstrings.ToLower(utils.TrimSpace(scheme))
}

// Protocol returns the HTTP protocol of request: HTTP/1.1 and HTTP/2.
func (r *DefaultReq) Protocol() string {
	return r.c.app.toString(r.c.fasthttp.Request.Header.Protocol())
}

// Query returns the query string parameter in the url.
// Defaults to empty string "" if the query doesn't exist.
// If a default value is given, it will return that value if the query doesn't exist.
// Returned value is only valid within the handler. Do not store any references.
// Make copies or use the Immutable setting to use the value outside the Handler.
func (r *DefaultReq) Query(key string, defaultValue ...string) string {
	return Query(r.c, key, defaultValue...)
}

// Queries returns a map of query parameters and their values.
//
// GET /?name=alex&wanna_cake=2&id=
// Queries()["name"] == "alex"
// Queries()["wanna_cake"] == "2"
// Queries()["id"] == ""
//
// GET /?field1=value1&field1=value2&field2=value3
// Queries()["field1"] == "value2"
// Queries()["field2"] == "value3"
//
// GET /?list_a=1&list_a=2&list_a=3&list_b[]=1&list_b[]=2&list_b[]=3&list_c=1,2,3
// Queries()["list_a"] == "3"
// Queries()["list_b[]"] == "3"
// Queries()["list_c"] == "1,2,3"
//
// GET /api/search?filters.author.name=John&filters.category.name=Technology&filters[customer][name]=Alice&filters[status]=pending
// Queries()["filters.author.name"] == "John"
// Queries()["filters.category.name"] == "Technology"
// Queries()["filters[customer][name]"] == "Alice"
// Queries()["filters[status]"] == "pending"
func (r *DefaultReq) Queries() map[string]string {
	app := r.c.app
	queryArgs := r.c.fasthttp.QueryArgs()

	m := make(map[string]string, queryArgs.Len())
	for key, value := range queryArgs.All() {
		m[app.toString(key)] = app.toString(value)
	}
	return m
}

// Query Retrieves the value of a query parameter from the request's URI.
// The function is generic and can handle query parameter values of different types.
// It takes the following parameters:
// - c: The context object representing the current request.
// - key: The name of the query parameter.
// - defaultValue: (Optional) The default value to return if the query parameter is not found or cannot be parsed.
// The function performs the following steps:
//  1. Type-asserts the context object to *DefaultCtx.
//  2. Retrieves the raw query parameter value from the request's URI.
//  3. Parses the raw value into the appropriate type based on the generic type parameter V.
//     If parsing fails, the function checks if a default value is provided. If so, it returns the default value.
//  4. Returns the parsed value.
//
// If the generic type cannot be matched to a supported type, the function returns the default value (if provided) or the zero value of type V.
//
// Example usage:
//
//	GET /?search=john&age=8
//	name := Query[string](c, "search") // Returns "john"
//	age := Query[int](c, "age") // Returns 8
//	unknown := Query[string](c, "unknown", "default") // Returns "default" since the query parameter "unknown" is not found
func Query[V GenericType](c Ctx, key string, defaultValue ...V) V {
	q := c.App().toString(c.RequestCtx().QueryArgs().Peek(key))
	v, err := genericParseType[V](q)
	if err != nil && len(defaultValue) > 0 {
		return defaultValue[0]
	}
	return v
}

// Range returns a struct containing the type and a slice of ranges.
func (r *DefaultReq) Range(size int64) (Range, error) {
	var (
		rangeData Range
		ranges    string
	)
	rangeStr := utils.TrimSpace(r.Get(HeaderRange))
	maxRanges := r.c.app.config.MaxRanges
	const maxRangePrealloc = 8
	prealloc := min(maxRanges, maxRangePrealloc)
	if prealloc > 0 {
		rangeData.Ranges = make([]RangeSet, 0, prealloc)
	}

	// parseBound parses a present (non-empty) range bound. A bound that is
	// not a valid integer makes the range-spec, and therefore the whole
	// ranges-specifier, invalid (RFC 9110 Section 14.1.1).
	parseBound := func(value string) (int64, error) {
		parsed, err := utils.ParseUint(value)
		if err != nil {
			return 0, ErrRangeMalformed
		}
		if parsed > (math.MaxUint64 >> 1) {
			return 0, ErrRangeMalformed
		}
		return int64(parsed), nil
	}

	before, after, found := strings.Cut(rangeStr, "=")
	if !found {
		return Range{}, ErrRangeMalformed
	}
	if !utils.EqualFold(utils.TrimSpace(before), "bytes") {
		// A range unit the server does not understand is not malformed: it
		// must be ignored (RFC 9110 Section 14.2), which only the caller can
		// do, so signal it distinctly. This check runs before any syntax
		// checks on the range-set, since the other-range grammar permits
		// characters (such as "=") that byte ranges do not.
		return Range{}, ErrRangeUnsupported
	}
	rangeData.Type = "bytes"
	if strings.IndexByte(after, '=') >= 0 {
		return Range{}, ErrRangeMalformed
	}
	ranges = utils.TrimSpace(after)

	var (
		singleRange  string
		moreRanges   = ranges
		elementCount int  // every list element, including empty ones (MaxRanges bound)
		sawRangeSpec bool // at least one non-empty range-spec was present
	)
	for moreRanges != "" {
		// Empty elements count toward MaxRanges too, so the cap bounds the
		// total parsing work per header, not just the accepted range-specs.
		elementCount++
		if elementCount > maxRanges {
			r.c.DefaultRes.Status(StatusRequestedRangeNotSatisfiable)
			r.c.DefaultRes.Set(HeaderContentRange, "bytes */"+utils.FormatInt(size)) //nolint:staticcheck // It is fine to ignore the static check
			return Range{}, ErrRangeTooLarge
		}

		singleRange = moreRanges
		if i := strings.IndexByte(moreRanges, ','); i >= 0 {
			singleRange = moreRanges[:i]
			moreRanges = utils.TrimSpace(moreRanges[i+1:])
		} else {
			moreRanges = ""
		}

		singleRange = utils.TrimSpace(singleRange)

		// RFC 9110 Section 5.6.1.2: recipients must parse and ignore a
		// reasonable number of empty list elements, e.g. "bytes=,0-5" is
		// equivalent to "bytes=0-5".
		if singleRange == "" {
			continue
		}
		sawRangeSpec = true

		var (
			startStr, endStr string
			i                int
		)
		if i = strings.IndexByte(singleRange, '-'); i == -1 {
			return Range{}, ErrRangeMalformed
		}
		startStr = utils.TrimSpace(singleRange[:i])
		endStr = utils.TrimSpace(singleRange[i+1:])

		var (
			start, end int64
			err        error
		)
		if startStr != "" {
			if start, err = parseBound(startStr); err != nil {
				return Range{}, err
			}
		}
		if endStr != "" {
			if end, err = parseBound(endStr); err != nil {
				return Range{}, err
			}
		}
		switch {
		case startStr == "" && endStr == "":
			// "-" carries neither a first-byte-pos nor a suffix-length and is
			// not a valid range-spec (RFC 9110 Section 14.1.1).
			return Range{}, ErrRangeMalformed
		case startStr == "": // -nnn (suffix range)
			start = max(size-end, 0)
			end = size - 1
		case endStr == "": // nnn- (open-ended range)
			end = size - 1
		default: // nnn-mmm
			// An int-range with a last-byte-pos less than its first-byte-pos
			// invalidates the whole ranges-specifier (RFC 9110 Section 14.1.1).
			if end < start {
				return Range{}, ErrRangeMalformed
			}
			if end > size-1 { // limit last-byte-pos to current length
				end = size - 1
			}
		}
		if start > end {
			// Syntactically valid but does not overlap the representation
			// (e.g. first-byte-pos beyond EOF or a zero-length suffix); skip
			// it and let the satisfiability check below decide.
			continue
		}
		rangeData.Ranges = append(rangeData.Ranges, RangeSet{
			Start: start,
			End:   end,
		})
	}
	if len(rangeData.Ranges) < 1 {
		if !sawRangeSpec {
			// Only empty list elements: there was no range-spec at all, so
			// the ranges-specifier is invalid rather than unsatisfiable.
			return Range{}, ErrRangeMalformed
		}
		r.c.DefaultRes.Status(StatusRequestedRangeNotSatisfiable)
		r.c.DefaultRes.Set(HeaderContentRange, "bytes */"+utils.FormatInt(size)) //nolint:staticcheck // It is fine to ignore the static check
		return rangeData, ErrRequestedRangeNotSatisfiable
	}

	return rangeData, nil
}

// Route returns the matched Route struct.
func (r *DefaultReq) Route() *Route {
	return r.c.Route()
}

// Subdomains returns a slice of subdomains from the host, excluding the last `offset` components.
// If the offset is negative or exceeds the number of subdomains, an empty slice is returned.
// If the offset is zero every label (no trimming) is returned.
func (r *DefaultReq) Subdomains(offset ...int) []string {
	o := 2
	if len(offset) > 0 {
		o = offset[0]
	}

	// Negative offset, return nothing.
	if o < 0 {
		return []string{}
	}

	// Normalize host according to RFC 3986
	host := r.Hostname()
	// Trim the trailing dot of a fully-qualified domain
	if strings.HasSuffix(host, ".") {
		host = utils.TrimRight(host, '.')
	}
	host = utilsstrings.ToLower(host)

	// Decode punycode labels only when necessary
	if strings.Contains(host, "xn--") {
		if u, err := idna.Lookup.ToUnicode(host); err == nil {
			host = utilsstrings.ToLower(u)
		}
	}

	// Return nothing for IP addresses
	ip := host
	if strings.HasPrefix(ip, "[") && strings.HasSuffix(ip, "]") {
		ip = ip[1 : len(ip)-1]
	}
	if utils.IsIPv4(ip) || utils.IsIPv6(ip) {
		return []string{}
	}

	// Use stack-allocated array for typical domain names (up to 8 labels)
	// This avoids heap allocation for most common cases
	var partsBuf [8]string
	parts := partsBuf[:0]

	for part := range strings.SplitSeq(host, ".") {
		parts = append(parts, part)
	}

	// offset == 0, caller wants everything.
	if o == 0 {
		// Need to return a copy since partsBuf is on the stack
		result := make([]string, len(parts))
		copy(result, parts)
		return result
	}

	// If we trim away the whole slice (or more), nothing remains.
	if o >= len(parts) {
		return []string{}
	}

	// Return a heap-allocated copy of the relevant portion
	result := make([]string, len(parts)-o)
	copy(result, parts[:len(parts)-o])
	return result
}

// Stale returns the inverse of Fresh, indicating if the client's cached response is considered stale.
func (r *DefaultReq) Stale() bool {
	return !r.Fresh()
}

// IsProxyTrusted checks trustworthiness of remote ip.
// If Config.TrustProxy false, it returns false.
// IsProxyTrusted can check remote ip by proxy ranges and ip map.
func (r *DefaultReq) IsProxyTrusted() bool {
	config := r.c.app.config
	if !config.TrustProxy {
		return false
	}

	remoteAddr := r.c.fasthttp.RemoteAddr()
	switch remoteAddr.(type) {
	case *net.UnixAddr:
		return config.TrustProxyConfig.UnixSocket
	case *net.TCPAddr, *net.UDPAddr:
		// Keep existing RemoteIP/IP-map/CIDR checks for TCP/UDP paths as-is.
	default:
		// Unknown address type: do not trust by default.
		return false
	}

	ip := r.c.fasthttp.RemoteIP()
	if ip == nil {
		return false
	}

	if (config.TrustProxyConfig.Loopback && ip.IsLoopback()) ||
		(config.TrustProxyConfig.Private && ip.IsPrivate()) ||
		(config.TrustProxyConfig.LinkLocal && ip.IsLinkLocalUnicast()) {
		return true
	}

	// Only stringify the IP when there is an exact-match map to look it up in;
	// ip.String() heap-allocates and is wasted work for CIDR-only configs.
	if len(config.TrustProxyConfig.ips) > 0 {
		if _, trusted := config.TrustProxyConfig.ips[ip.String()]; trusted {
			return true
		}
	}

	for _, ipNet := range config.TrustProxyConfig.ranges {
		if ipNet.Contains(ip) {
			return true
		}
	}

	return false
}

// IsFromLocal will return true if request came from a loopback IP.
func (r *DefaultReq) IsFromLocal() bool {
	if ip := r.c.fasthttp.RemoteIP(); ip != nil {
		return ip.IsLoopback()
	}
	return false
}

// IsFromUnixSocket returns true if the request arrived over a Unix domain socket.
func (r *DefaultReq) IsFromUnixSocket() bool {
	_, ok := r.c.fasthttp.RemoteAddr().(*net.UnixAddr)
	return ok
}

func (r *DefaultReq) getBody() []byte {
	return r.c.app.GetBytes(r.c.fasthttp.Request.Body())
}

package proxy

import (
	"context"
	"crypto/tls"
	"errors"
	"fmt"
	"net"
	"net/url"
	"strings"
	"sync/atomic"
	"time"

	"github.com/gofiber/fiber/v3"
	"github.com/gofiber/utils/v2"
	"github.com/valyala/fasthttp"
)

// dnsLookupTimeout bounds DNS resolution performed during upstream
// validation and dialing, so a slow or unresponsive resolver cannot hang
// a request (or application startup) indefinitely.
const dnsLookupTimeout = 5 * time.Second

// Supported upstream schemes. Defined as constants so the literals don't
// trip the goconst linter when referenced from policy defaults, scheme
// comparisons, and redirect downgrade checks.
const (
	schemeHTTP  = "http"
	schemeHTTPS = "https"
)

// defaultAllowedSchemes is the internal, read-only allowlist used as the
// fallback inside schemeAllowed when a policy carries no AllowedSchemes.
// It is never handed out by reference: DefaultSecurityPolicy() and
// normalizePolicy() copy it before it can reach the exported
// SecurityPolicy.AllowedSchemes field, so nothing outside this file can
// mutate the backing array.
var defaultAllowedSchemes = []string{schemeHTTP, schemeHTTPS}

// httpsSchemeBytes is the byte form of "https" used by redirect
// downgrade checks. Stored once so the resolveRedirect hot path doesn't
// allocate []byte("https") on every hop.
var httpsSchemeBytes = []byte(schemeHTTPS)

// Sentinel errors returned when an upstream target violates the configured
// proxy security policy.
var (
	// ErrUpstreamSchemeNotAllowed is returned when the proxied URL uses a
	// scheme outside the configured allowlist (default: http, https).
	ErrUpstreamSchemeNotAllowed = errors.New("proxy: upstream scheme is not allowed")

	// ErrUpstreamHostInvalid is returned when the proxied URL is missing a
	// host or cannot be parsed.
	ErrUpstreamHostInvalid = errors.New("proxy: upstream host is empty or invalid")

	// ErrUpstreamHostBlocked is returned when the proxied URL resolves to
	// an address inside a blocked range (loopback, RFC 1918 private,
	// link-local, multicast, unspecified, or CGNAT) and AllowPrivateIPs
	// is false.
	ErrUpstreamHostBlocked = errors.New("proxy: upstream host resolves to a blocked address")

	// ErrRedirectDowngrade is returned when DoRedirects encounters a
	// redirect from an HTTPS upstream to a plaintext HTTP target and
	// AllowHTTPSDowngrade is false.
	ErrRedirectDowngrade = errors.New("proxy: HTTPS to HTTP redirect blocked")
)

// SecurityPolicy controls runtime security restrictions applied to the
// proxy.Do, proxy.Forward, proxy.DoRedirects, proxy.DoTimeout, and
// proxy.DoDeadline runtime helpers as well as Balancer instances that
// do not supply their own policy via Config.SecurityPolicy.
type SecurityPolicy struct {
	// AllowedSchemes restricts the URL schemes accepted as upstream
	// targets. Empty defaults to []string{schemeHTTP, schemeHTTPS}.
	AllowedSchemes []string

	// AllowPrivateIPs allows upstream hosts to resolve to loopback,
	// private (RFC 1918), link-local, multicast, unspecified, or CGNAT
	// (RFC 6598) addresses. SECURITY: enabling this exposes the proxy
	// to SSRF attacks against internal services such as cloud
	// metadata endpoints. Default: false.
	//
	// DNS-rebinding scope: when false, the resolved IP is re-validated at
	// dial time, not only up front, so a malicious resolver cannot swap a
	// public answer (seen during validation) for a private one at connect
	// time. Balancer installs a guarded Dial on each HostClient it builds;
	// the runtime helpers — Do, DoRedirects, DoTimeout, DoDeadline,
	// Forward, DomainForward, BalancerForward — install the same guard on
	// the shared/user-supplied *fasthttp.Client they dispatch through.
	//
	// The default client and clients registered via WithClient are guarded
	// before first use and are fully protected. A client passed as a
	// per-call variadic argument is guarded on first use, so any host it had
	// already dialed keeps a cached, pre-guard HostClient; register such a
	// client via WithClient (or hand the proxy a dedicated, unused client)
	// for the full guarantee. The only path with no guard at all is a custom
	// Balancer Config.Client (*fasthttp.LBClient): its underlying dialers
	// are the caller's responsibility.
	AllowPrivateIPs bool

	// AllowHTTPSDowngrade permits proxy.DoRedirects to follow redirects
	// from HTTPS upstreams to plaintext HTTP URLs. SECURITY: enabling
	// this can leak credentials or session cookies in plaintext.
	// Default: false.
	AllowHTTPSDowngrade bool

	// KeepHopByHopHeaders disables the RFC 7230 §6.1 hop-by-hop header
	// stripping applied to both the outbound request and the inbound
	// response. SECURITY: enabling this can enable request smuggling
	// and proxy-auth credential forwarding. Default: false.
	KeepHopByHopHeaders bool
}

// DefaultSecurityPolicy returns the secure-by-default proxy security
// policy. Callers can clone it, mutate selected fields, and pass it back
// via Config.SecurityPolicy or WithSecurityPolicy.
//
// AllowedSchemes is a freshly allocated slice on every call: the field
// is exported, so returning the shared defaultAllowedSchemes backing
// array would let a caller doing e.g. policy.AllowedSchemes[0] = "file"
// silently weaken the package defaults and every policy that references
// them.
func DefaultSecurityPolicy() SecurityPolicy {
	return SecurityPolicy{
		AllowedSchemes:      append([]string(nil), defaultAllowedSchemes...),
		AllowPrivateIPs:     false,
		AllowHTTPSDowngrade: false,
		KeepHopByHopHeaders: false,
	}
}

// activePolicy is the global SecurityPolicy consulted by every
// non-Balancer proxy request. Reads are lock-free via atomic.Pointer.
// The pointed-to SecurityPolicy is treated as immutable once installed:
// WithSecurityPolicy is the only writer, and it stores a value whose
// AllowedSchemes slice has been deep-copied to defend against later
// mutation by the caller.
var activePolicy atomic.Pointer[SecurityPolicy]

// dnsResolver is the resolver used for SSRF validation lookups. It defaults
// to net.DefaultResolver and is only ever swapped by tests, atomically, so a
// concurrent validation lookup never races the swap. Tests use this seam
// rather than mutating the process-global net.DefaultResolver — which
// fasthttp and the net package read from background dial goroutines, making a
// direct swap a data race under -race.
var dnsResolver atomic.Pointer[net.Resolver]

func init() {
	def := DefaultSecurityPolicy()
	activePolicy.Store(&def)
	dnsResolver.Store(net.DefaultResolver)
}

// normalizePolicy returns a copy of policy whose AllowedSchemes slice is
// always freshly allocated. This guarantees callers cannot mutate the
// global allowlist out from under a balancer (or another goroutine) by
// retaining a reference to the slice they passed in — including the
// package-level defaultAllowedSchemes, which must never be handed out by
// reference. The defensive copy happens at install time only — readers
// consume the immutable result via activePolicy.Load() without further
// copying.
func normalizePolicy(policy SecurityPolicy) SecurityPolicy {
	if len(policy.AllowedSchemes) == 0 {
		policy.AllowedSchemes = append([]string(nil), defaultAllowedSchemes...)
	} else {
		policy.AllowedSchemes = append([]string(nil), policy.AllowedSchemes...)
	}
	return policy
}

// WithSecurityPolicy installs policy as the global default consulted by
// proxy.Do, proxy.Forward, proxy.DoRedirects, proxy.DoTimeout, and
// proxy.DoDeadline (and by Balancer instances that do not set
// Config.SecurityPolicy). It returns the previously installed policy so
// callers can restore it — useful in tests that need to relax
// the policy for a single scope.
func WithSecurityPolicy(policy SecurityPolicy) SecurityPolicy {
	normalized := normalizePolicy(policy)
	prev := activePolicy.Swap(&normalized)
	if prev == nil {
		return DefaultSecurityPolicy()
	}
	return *prev
}

// currentSecurityPolicy returns a snapshot of the active global policy.
// The snapshot is by-value, but its AllowedSchemes slice header aliases
// the immutable backing array installed by WithSecurityPolicy — no copy
// is taken on the read path.
func currentSecurityPolicy() SecurityPolicy {
	return *activePolicy.Load()
}

// resolvePolicy returns override when non-nil; otherwise the current
// global policy. Both Balancer and the runtime helpers funnel through
// this so a single source of truth governs upstream validation and
// header stripping. Override paths still copy AllowedSchemes so a
// caller passing Config.SecurityPolicy by reference cannot mutate the
// Balancer's view after construction.
func resolvePolicy(override *SecurityPolicy) SecurityPolicy {
	if override != nil {
		return normalizePolicy(*override)
	}
	return currentSecurityPolicy()
}

// hopByHopHeaders are the RFC 7230 §6.1 connection-level headers that
// intermediaries must not forward. Stripping these prevents request
// smuggling (Transfer-Encoding/TE), proxy-credential forwarding
// (Proxy-Authorization), and protocol-upgrade leaks.
var hopByHopHeaders = []string{
	fiber.HeaderConnection,
	fiber.HeaderKeepAlive,
	fiber.HeaderProxyAuthenticate,
	fiber.HeaderProxyAuthorization,
	fiber.HeaderTE,
	fiber.HeaderTrailer,
	fiber.HeaderTransferEncoding,
	fiber.HeaderUpgrade,
}

// stripHopByHopRequestHeaders removes RFC 7230 §6.1 hop-by-hop headers
// from req. Callers can pass header names in except to preserve specific
// headers — used by the legacy KeepConnectionHeader option to retain the
// literal Connection header while still dropping the other hop-by-hop
// headers.
func stripHopByHopRequestHeaders(req *fasthttp.Request, except ...string) {
	// Headers listed in Connection must be removed first so the
	// listing is honored before the Connection field itself is dropped.
	delConnectionListedHeaders(&req.Header, req.Header.PeekAll(fiber.HeaderConnection))
	for _, h := range hopByHopHeaders {
		if containsFold(except, h) {
			continue
		}
		req.Header.Del(h)
	}
}

// stripHopByHopResponseHeaders applies the same filtering on the way
// back, so upstream cannot leak connection-scoped state to the client.
func stripHopByHopResponseHeaders(res *fasthttp.Response, except ...string) {
	delConnectionListedHeaders(&res.Header, res.Header.PeekAll(fiber.HeaderConnection))
	for _, h := range hopByHopHeaders {
		if containsFold(except, h) {
			continue
		}
		res.Header.Del(h)
	}
}

func containsFold(haystack []string, needle string) bool {
	for _, h := range haystack {
		if utils.EqualFold(h, needle) {
			return true
		}
	}
	return false
}

// headerDeleter is the Del method shared by fasthttp's request and
// response header types.
type headerDeleter interface {
	Del(key string)
}

// delConnectionListedHeaders deletes every comma-separated header name
// listed inside one or more Connection header fields, per RFC 7230 §6.1,
// without copying the values or collecting the names into a slice. The
// names handed to Del alias the Connection value buffers; that is sound
// because fasthttp's Del only re-slices the header's entry list — it never
// rewrites other entries' key/value buffers — and Del does not retain the
// name after returning.
func delConnectionListedHeaders(h headerDeleter, values [][]byte) {
	for _, v := range values {
		for name := range strings.SplitSeq(utils.UnsafeString(v), ",") {
			name = utils.TrimSpace(name)
			if name != "" {
				h.Del(name)
			}
		}
	}
}

// parseUpstream returns the parsed url.URL for raw. Hosts without an
// explicit scheme default to http:// to match the historical Balancer
// behavior where bare "host:port" entries were accepted.
func parseUpstream(raw string) (*url.URL, error) {
	raw = utils.TrimSpace(raw)
	if raw == "" {
		return nil, ErrUpstreamHostInvalid
	}
	if !strings.Contains(raw, "://") {
		raw = "http://" + raw
	}
	u, err := url.Parse(raw)
	if err != nil {
		return nil, fmt.Errorf("proxy: parse upstream %q: %w", raw, err)
	}
	return u, nil
}

// validateUpstream parses raw, enforces the scheme allowlist, and unless
// the policy permits private addresses, resolves the hostname and
// rejects responses that include any blocked address. Rejecting on a
// single blocked answer mitigates DNS rebinding attempts in which the
// resolver returns a mix of public and private IPs.
func validateUpstream(raw string, policy SecurityPolicy) (*url.URL, error) {
	u, err := parseUpstreamScheme(raw, policy)
	if err != nil {
		return nil, err
	}
	if policy.AllowPrivateIPs {
		return u, nil
	}
	if err := validateHostForSSRF(u.Hostname()); err != nil {
		return nil, err
	}
	return u, nil
}

// parseUpstreamScheme parses raw and enforces the scheme allowlist and
// host presence without performing any DNS resolution. url.Parse can
// leave Host set while Hostname() is empty (e.g. "http://:8080"), so the
// presence check uses Hostname.
func parseUpstreamScheme(raw string, policy SecurityPolicy) (*url.URL, error) {
	u, err := parseUpstream(raw)
	if err != nil {
		return nil, err
	}
	if !schemeAllowed(u.Scheme, policy.AllowedSchemes) {
		return nil, fmt.Errorf("%w: %q", ErrUpstreamSchemeNotAllowed, u.Scheme)
	}
	if u.Hostname() == "" {
		return nil, ErrUpstreamHostInvalid
	}
	return u, nil
}

// validateUpstreamForBalancer validates a statically configured Balancer
// upstream. It enforces the scheme allowlist and rejects IP-literal hosts
// in blocked ranges, but defers hostname resolution to the SSRF-guarded
// dialer (see newSSRFDialer). Deferring DNS keeps a transient resolver
// failure at startup from panicking the application (e.g. crash loops in
// container orchestrators) and re-checks the resolved IP on every dial,
// which also defeats DNS-rebinding.
func validateUpstreamForBalancer(raw string, policy SecurityPolicy) (*url.URL, error) {
	u, err := parseUpstreamScheme(raw, policy)
	if err != nil {
		return nil, err
	}
	if policy.AllowPrivateIPs {
		return u, nil
	}
	if ip := net.ParseIP(trimBrackets(u.Hostname())); ip != nil && isBlockedIP(ip) {
		return nil, fmt.Errorf("%w: %s", ErrUpstreamHostBlocked, ip)
	}
	return u, nil
}

// schemeAllowed reports whether scheme is on the allowlist. An empty
// allowlist falls back to the secure defaults.
func schemeAllowed(scheme string, allowed []string) bool {
	if scheme == "" {
		return false
	}
	if len(allowed) == 0 {
		allowed = defaultAllowedSchemes
	}
	for _, s := range allowed {
		if utils.EqualFold(s, scheme) {
			return true
		}
	}
	return false
}

// trimBrackets removes the surrounding "[" / "]" from an IPv6 literal
// (defensive — url.Hostname() typically does this already). The fiber
// utils Trim helpers only accept a single byte cutset, so we apply
// TrimLeft + TrimRight to handle the bracket pair.
func trimBrackets(host string) string {
	return utils.TrimRight(utils.TrimLeft(host, '['), ']')
}

// validateHostForSSRF rejects hostnames that resolve to addresses inside
// the blocked ranges. The IP literal shortcut avoids DNS lookups when
// the host is already a numeric address.
func validateHostForSSRF(host string) error {
	if host == "" {
		return ErrUpstreamHostInvalid
	}
	// strip brackets from IPv6 literals (url.Hostname already does this
	// in most cases, but keep the guard for defensive callers).
	host = trimBrackets(host)
	if ip := net.ParseIP(host); ip != nil {
		if isBlockedIP(ip) {
			return fmt.Errorf("%w: %s", ErrUpstreamHostBlocked, ip)
		}
		return nil
	}
	// Bound the lookup so a slow resolver cannot stall the caller.
	ctx, cancel := context.WithTimeout(context.Background(), dnsLookupTimeout)
	defer cancel()
	addrs, err := dnsResolver.Load().LookupIPAddr(ctx, host)
	if err != nil {
		return fmt.Errorf("%w: %s lookup failed: %w", ErrUpstreamHostBlocked, host, err)
	}
	if len(addrs) == 0 {
		return fmt.Errorf("%w: %s has no addresses", ErrUpstreamHostBlocked, host)
	}
	for _, addr := range addrs {
		if isBlockedIP(addr.IP) {
			return fmt.Errorf("%w: %s -> %s", ErrUpstreamHostBlocked, host, addr.IP)
		}
	}
	return nil
}

// newSSRFDialer returns a fasthttp DialFunc that resolves the target host
// (with a bounded timeout), rejects the connection if any resolved
// address falls in a blocked range, and then dials a validated address.
// Performing the check at dial time — rather than only up front — defeats
// DNS-rebinding attacks (the check/use gap) where a resolver returns a
// public address during validation and a private one at connect time. It
// is only installed when the active policy disallows private IPs.
//
//nolint:revive // dialDualStack mirrors fasthttp.HostClient.DialDualStack
func newSSRFDialer(dialDualStack bool) fasthttp.DialFunc {
	dialer := &net.Dialer{Timeout: dnsLookupTimeout}
	return func(addr string) (net.Conn, error) {
		host, port, err := net.SplitHostPort(addr)
		if err != nil {
			return nil, fmt.Errorf("proxy: invalid dial address %q: %w", addr, err)
		}
		ips, err := resolveAndValidateHost(host)
		if err != nil {
			return nil, err
		}
		return dialValidatedIPs(ips, host, port, dialDualStack, dialer.Dial)
	}
}

// resolveAndValidateHost looks up host (or treats it as an IP literal),
// then enforces the SSRF blocklist on every returned address. A single
// blocked answer fails the whole resolution so a mixed public/private
// reply cannot slip past the guard.
func resolveAndValidateHost(host string) ([]net.IP, error) {
	var ips []net.IP
	if ip := net.ParseIP(host); ip != nil {
		ips = []net.IP{ip}
	} else {
		ctx, cancel := context.WithTimeout(context.Background(), dnsLookupTimeout)
		defer cancel()
		resolved, lerr := dnsResolver.Load().LookupIPAddr(ctx, host)
		if lerr != nil {
			return nil, fmt.Errorf("%w: %s lookup failed: %w", ErrUpstreamHostBlocked, host, lerr)
		}
		for _, r := range resolved {
			ips = append(ips, r.IP)
		}
	}
	for _, ip := range ips {
		if isBlockedIP(ip) {
			return nil, fmt.Errorf("%w: %s -> %s", ErrUpstreamHostBlocked, host, ip)
		}
	}
	return ips, nil
}

// ssrfDialFunc is the (network, address) -> conn signature consumed by
// dialValidatedIPs. It accepts the standard library *net.Dialer's Dial
// method directly, and lets tests inject a deterministic stub.
type ssrfDialFunc func(network, address string) (net.Conn, error)

// dialValidatedIPs walks ips and tries to dial the first non-skipped
// address. When dialDualStack is false, IPv6 addresses are skipped to
// match fasthttp's IPv4-only default. If every candidate is skipped, a
// "no usable address" error is returned; otherwise the last dial error
// is propagated so the caller can see why each attempt failed.
//
//nolint:revive // dialDualStack mirrors fasthttp.HostClient.DialDualStack
func dialValidatedIPs(ips []net.IP, host, port string, dialDualStack bool, dial ssrfDialFunc) (net.Conn, error) {
	var lastErr error
	for _, ip := range ips {
		// Mirror fasthttp's default of IPv4-only unless DialDualStack.
		if !dialDualStack && ip.To4() == nil {
			continue
		}
		conn, derr := dial("tcp", net.JoinHostPort(ip.String(), port))
		if derr == nil {
			return conn, nil
		}
		lastErr = derr
	}
	if lastErr == nil {
		lastErr = fmt.Errorf("%w: %s has no usable address", ErrUpstreamHostBlocked, host)
	}
	return nil, lastErr
}

// installHostClientGuard fits hc with the policy-aware, dial-time SSRF
// guard. It is installed through fasthttp.Client.ConfigureClient, which
// runs once per HostClient at creation — so the guard is present before the
// first dial to that host and, crucially, covers BOTH dial code paths:
// fasthttp's callDialFunc prefers DialTimeout over Dial, so guarding only
// Dial would let a client that sets DialTimeout dial unvalidated. We wrap
// DialTimeout when present (preserving its per-request timeout) and always
// wrap Dial so the nil-DialTimeout and default-dialer paths are guarded too.
func installHostClientGuard(hc *fasthttp.HostClient) {
	if hc.DialTimeout != nil {
		hc.DialTimeout = newGuardedClientDialerWithTimeout(hc.DialTimeout, hc.DialDualStack)
	}
	hc.Dial = newGuardedClientDialer(hc.Dial, hc.DialDualStack)
}

// guardedDial is the shared core of both dialer guards. When the active
// policy allows private IPs the caller has opted into internal targets, so
// it delegates unchanged. Otherwise it resolves and validates the host,
// then dials the exact validated IP via dialValidated — closing the
// DNS-rebinding check/use window the up-front validateUpstream lookup
// leaves open. The policy is read fresh on every dial because a shared
// client outlives any single policy snapshot.
//
//nolint:revive // dialDualStack mirrors fasthttp.Client.DialDualStack
func guardedDial(
	addr string,
	dialDualStack bool,
	delegate func(addr string) (net.Conn, error),
	dialValidated ssrfDialFunc,
) (net.Conn, error) {
	if currentSecurityPolicy().AllowPrivateIPs {
		return delegate(addr)
	}
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, fmt.Errorf("proxy: invalid dial address %q: %w", addr, err)
	}
	ips, err := resolveAndValidateHost(host)
	if err != nil {
		return nil, err
	}
	return dialValidatedIPs(ips, host, port, dialDualStack, dialValidated)
}

// newGuardedClientDialer wraps orig with the SSRF guard. Unlike
// newSSRFDialer — whose blocking is unconditional because Balancer only
// installs it when the policy forbids private IPs — this dialer is
// consulted by clients that outlive a single policy snapshot, so it
// re-reads the active global policy on every dial. When the caller supplied
// their own dialer it is run in both paths so custom transport is preserved
// while a blocked-policy connection still targets the validated address.
//
// When orig is nil the two paths differ, matching newSSRFDialer: the
// delegate (private-IPs-allowed) path hands the raw address to fasthttp's
// default dialer (Dial/DialDualStack), while the validated (blocked-policy)
// path connects to the already-checked IP with a net.Dialer bounded by
// dnsLookupTimeout — fasthttp.Dial is not reused there because the target is
// a literal IP that needs no re-resolution and the explicit timeout bounds
// the connect.
//
//nolint:revive // dialDualStack mirrors fasthttp.Client.DialDualStack
func newGuardedClientDialer(orig fasthttp.DialFunc, dialDualStack bool) fasthttp.DialFunc {
	dialer := &net.Dialer{Timeout: dnsLookupTimeout}
	delegate := func(addr string) (net.Conn, error) {
		if orig != nil {
			return orig(addr)
		}
		if dialDualStack {
			return fasthttp.DialDualStack(addr)
		}
		return fasthttp.Dial(addr)
	}
	dialValidated := func(_, address string) (net.Conn, error) {
		if orig != nil {
			return orig(address)
		}
		return dialer.Dial("tcp", address)
	}
	return func(addr string) (net.Conn, error) {
		return guardedDial(addr, dialDualStack, delegate, dialValidated)
	}
}

// newGuardedClientDialerWithTimeout is the DialFuncWithTimeout counterpart
// of newGuardedClientDialer. orig is always non-nil here (installed only
// when the HostClient already carries a DialTimeout), and the per-request
// timeout is threaded through both the delegate and the validated dial so
// the caller's timeout semantics survive the guard.
//
//nolint:revive // dialDualStack mirrors fasthttp.Client.DialDualStack
func newGuardedClientDialerWithTimeout(orig fasthttp.DialFuncWithTimeout, dialDualStack bool) fasthttp.DialFuncWithTimeout {
	return func(addr string, timeout time.Duration) (net.Conn, error) {
		delegate := func(a string) (net.Conn, error) {
			return orig(a, timeout)
		}
		dialValidated := func(_, address string) (net.Conn, error) {
			return orig(address, timeout)
		}
		return guardedDial(addr, dialDualStack, delegate, dialValidated)
	}
}

// isBlockedIP reports whether ip falls inside a range that proxy
// upstreams must not reach by default. Loopback, unspecified, RFC 1918
// private, link-local (including the 169.254.169.254 cloud-metadata
// address), multicast, and RFC 6598 CGNAT ranges are blocked.
//
// IPv6 transition addresses are handled in two ways so a blocked IPv4 cannot
// be smuggled past as an IPv6 literal. Deprecated tunneling and local-use
// ranges (6to4, Teredo, NAT64 local-use) are blocked in their entirety by
// isBlockedIPv6TransitionRange — their embedded IPv4 sits at an
// operator-dependent offset, and none has a legitimate use as a proxy
// upstream. The remaining wrappers whose embedded IPv4 is unambiguous and may
// legitimately be public (NAT64 well-known prefix, IPv4-compatible, ISATAP)
// are unwrapped by embeddedIPv4 and re-checked against the same blocklist.
func isBlockedIP(ip net.IP) bool {
	if ip == nil {
		return true
	}
	if ip.IsLoopback() || ip.IsUnspecified() || ip.IsPrivate() ||
		ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() ||
		ip.IsMulticast() || ip.IsInterfaceLocalMulticast() {
		return true
	}
	if v4 := ip.To4(); v4 != nil && v4[0] == 100 && v4[1] >= 64 && v4[1] <= 127 {
		return true
	}
	// Block deprecated / local-use IPv6 transition ranges wholesale (see the
	// helper for the rationale). Done before the embeddedIPv4 unwrap because
	// their embedded IPv4 offset is not fixed.
	if isBlockedIPv6TransitionRange(ip) {
		return true
	}
	// Look through the unambiguous wrappers to the embedded IPv4 and apply the
	// same blocklist. Some stacks route these to the embedded address, so a
	// private target could otherwise be reached via such a literal (the
	// IPv4-mapped ::ffff:a.b.c.d form is already handled above because
	// net.IP.To4 exposes it).
	if embedded := embeddedIPv4(ip); embedded != nil && isBlockedIP(embedded) {
		return true
	}
	return false
}

// isBlockedIPv6TransitionRange reports whether ip belongs to an IPv6
// transition range that must be blocked in its entirety:
//
//   - 6to4         2002::/16        (RFC 3056) — deprecated by RFC 7526.
//   - Teredo       2001:0000::/32   (RFC 4380) — a private IPv4 can hide in
//     either the un-obfuscated server field (bytes [4:8]) or the obfuscated
//     client field (bytes [12:16]).
//   - NAT64 local  64:ff9b:1::/48   (RFC 8215) — local-use only; RFC 8215 §3
//     forbids it on the public Internet, and RFC 6052 lets the embedded IPv4
//     sit anywhere from a /32 to a /96 boundary.
//
// Because the embedded IPv4 offset depends on operator configuration,
// unwrapping a single position would leave a bypass; blocking the whole range
// is both safer and simpler. This mirrors the CIDR-level handling in Gitea's
// and Coder's SSRF guards.
func isBlockedIPv6TransitionRange(ip net.IP) bool {
	ip16 := ip.To16()
	if ip16 == nil || ip.To4() != nil {
		return false
	}
	switch {
	case ip16[0] == 0x20 && ip16[1] == 0x02: // 6to4 2002::/16
		return true
	case ip16[0] == 0x20 && ip16[1] == 0x01 && ip16[2] == 0x00 && ip16[3] == 0x00: // Teredo 2001:0000::/32
		return true
	case ip16[0] == 0x00 && ip16[1] == 0x64 && ip16[2] == 0xff && ip16[3] == 0x9b &&
		ip16[4] == 0x00 && ip16[5] == 0x01: // NAT64 local-use 64:ff9b:1::/48
		return true
	}
	return false
}

// embeddedIPv4 returns the IPv4 address embedded in an IPv6 transition
// address, or nil for anything else. It only handles wrappers whose embedded
// IPv4 has a fixed, unambiguous offset and can legitimately be a public host:
//
//   - NAT64 well-known prefix 64:ff9b::/96 (RFC 6052) — defined only at /96,
//     so the embedded IPv4 is always the trailing 32 bits and is commonly used
//     to reach public IPv4 hosts from IPv6-only networks.
//   - ISATAP (RFC 5214) — interface identifier 00-00-5E-FE or 02-00-5E-FE
//     followed by the embedded IPv4 in the trailing 32 bits. The prefix is an
//     ordinary global one, so there is no dedicated range to block wholesale.
//   - SIIT IPv4-translated ::ffff:0:0/96 (RFC 2765) — 0xffff marker in bytes
//     [8:10], zero in [10:12], embedded IPv4 in the trailing 32 bits.
//   - IPv4-compatible ::a.b.c.d (RFC 4291) — trailing 32 bits.
//
// Deprecated tunneling / local-use ranges with operator-dependent embedding
// offsets (6to4, Teredo, NAT64 local-use) are intentionally NOT unwrapped here;
// isBlockedIPv6TransitionRange blocks them wholesale instead. The IPv4-mapped
// form (::ffff:a.b.c.d, 0xffff marker in bytes [10:12]) is also excluded:
// net.IP.To4 already surfaces its IPv4, so isBlockedIP checks it directly.
func embeddedIPv4(ip net.IP) net.IP {
	ip16 := ip.To16()
	if ip16 == nil || ip.To4() != nil {
		return nil
	}
	// NAT64 well-known prefix 64:ff9b::/96 (RFC 6052).
	if ip16[0] == 0x00 && ip16[1] == 0x64 && ip16[2] == 0xff && ip16[3] == 0x9b &&
		allZero(ip16[4:12]) {
		return net.IPv4(ip16[12], ip16[13], ip16[14], ip16[15])
	}
	// ISATAP (RFC 5214): interface identifier ::0:5efe:a.b.c.d or
	// ::200:5efe:a.b.c.d — the 5e:fe marker (with the IANA OUI and the
	// universal/local bit in ip16[8]) precedes the embedded IPv4.
	if ip16[9] == 0x00 && ip16[10] == 0x5e && ip16[11] == 0xfe &&
		(ip16[8] == 0x00 || ip16[8] == 0x02) {
		return net.IPv4(ip16[12], ip16[13], ip16[14], ip16[15])
	}
	// SIIT IPv4-translated ::ffff:0:a.b.c.d (RFC 2765, prefix ::ffff:0:0/96):
	// the 0xffff marker sits in bytes [8:10] with [10:12] zero, and the
	// embedded IPv4 is the trailing 32 bits. This is distinct from the
	// IPv4-mapped form (::ffff:a.b.c.d, marker in bytes [10:12]) that
	// net.IP.To4 already exposes, so it is unwrapped here.
	if allZero(ip16[:8]) && ip16[8] == 0xff && ip16[9] == 0xff &&
		ip16[10] == 0x00 && ip16[11] == 0x00 {
		return net.IPv4(ip16[12], ip16[13], ip16[14], ip16[15])
	}
	// IPv4-compatible ::a.b.c.d (first 12 bytes zero). :: and ::1 have already
	// been classified above, so treat any remaining all-zero-prefix address as
	// a wrapper around its trailing IPv4.
	if allZero(ip16[:12]) {
		return net.IPv4(ip16[12], ip16[13], ip16[14], ip16[15])
	}
	return nil
}

func allZero(b []byte) bool {
	for _, x := range b {
		if x != 0 {
			return false
		}
	}
	return true
}

// secureTLSConfig returns a clone of cfg with a TLS 1.2 floor. The
// caller's tls.Config is never mutated so per-host clients can share an
// immutable template without surprise.
func secureTLSConfig(cfg *tls.Config) *tls.Config {
	if cfg == nil {
		return &tls.Config{MinVersion: tls.VersionTLS12}
	}
	cloned := cfg.Clone()
	if cloned.MinVersion == 0 {
		cloned.MinVersion = tls.VersionTLS12
	}
	return cloned
}

// joinUpstreamPath returns a URL string formed by combining an already
// validated upstream base with a request path supplied by the client.
// The request path's authority component (if any) is discarded so
// crafted inputs like "//attacker.example/foo" or "@attacker" cannot
// change the host the proxy connects to.
func joinUpstreamPath(base *url.URL, requestPath string) string {
	if base == nil {
		return ""
	}
	// Fast path: the common production case is a base with no path
	// prefix and a request path that's already in clean origin form. In
	// that case the slow path's url.Parse + URL.String() round-trip
	// produces a string identical to base.Scheme + "://" + base.Host +
	// requestPath, so build the result directly with one allocation.
	// canFastJoinPath rejects any input that could collide with the
	// security-relevant patterns the slow path handles
	// (//-authority injection, @-authority injection, :-scheme
	// injection, control bytes). Anything it rejects falls through to
	// the slow path; the FuzzJoinUpstreamPath suite guards the
	// boundary.
	if baseIsPlainOrigin(base) && canFastJoinPath(requestPath) {
		var sb strings.Builder
		sb.Grow(len(base.Scheme) + len("://") + len(base.Host) + len(requestPath))
		// strings.Builder.WriteString always returns nil per the
		// documented contract; the errors are unused on purpose.
		sb.WriteString(base.Scheme) //nolint:errcheck // strings.Builder cannot fail
		sb.WriteString("://")       //nolint:errcheck // strings.Builder cannot fail
		sb.WriteString(base.Host)   //nolint:errcheck // strings.Builder cannot fail
		sb.WriteString(requestPath) //nolint:errcheck // strings.Builder cannot fail
		return sb.String()
	}
	out := *base
	if requestPath == "" {
		return out.String()
	}
	// A leading "//" makes Go's url.Parse treat the value as a
	// network-path reference and parse a new authority. Collapse it to
	// a single slash so the host stays pinned to the configured base.
	for strings.HasPrefix(requestPath, "//") {
		requestPath = "/" + utils.TrimLeft(requestPath, '/')
	}
	if requestPath[0] != '/' && requestPath[0] != '?' && requestPath[0] != '#' {
		requestPath = "/" + requestPath
	}
	parsed, err := url.Parse(requestPath)
	if err != nil || parsed.Host != "" || parsed.Scheme != "" {
		// Either the path failed to parse cleanly or it introduced a
		// new authority. Treat the remainder as an opaque path, but
		// preserve any path prefix configured on the upstream base so
		// a malformed request can't silently bypass it (e.g.
		// "http://upstream/api" + "/%zz" must stay rooted at "/api").
		fallback := "/" + utils.TrimLeft(requestPath, '/')
		if base.Path != "" {
			fallback = strings.TrimSuffix(base.Path, "/") + "/" + strings.TrimPrefix(fallback, "/")
		}
		out.Path = fallback
		out.RawPath = ""
		out.RawQuery = ""
		out.Fragment = ""
		return out.String()
	}
	if parsed.Path != "" {
		// Preserve any path prefix configured on the upstream base (e.g.
		// "http://upstream/api" + "/foo" -> "http://upstream/api/foo")
		// rather than overwriting it with the request path alone.
		out.Path = strings.TrimSuffix(base.Path, "/") + "/" + strings.TrimPrefix(parsed.Path, "/")
		if base.RawPath != "" || parsed.RawPath != "" {
			baseRaw := base.RawPath
			if baseRaw == "" {
				baseRaw = base.Path
			}
			parsedRaw := parsed.RawPath
			if parsedRaw == "" {
				parsedRaw = parsed.Path
			}
			out.RawPath = strings.TrimSuffix(baseRaw, "/") + "/" + strings.TrimPrefix(parsedRaw, "/")
		}
	}
	out.RawQuery = parsed.RawQuery
	out.Fragment = parsed.Fragment
	return out.String()
}

// baseIsPlainOrigin reports whether base carries only a scheme + host
// — no path prefix, userinfo, query, fragment, or opaque component.
// Any of those forces the slow path because the splice cannot
// reproduce them with a simple concatenation.
func baseIsPlainOrigin(base *url.URL) bool {
	return base.Path == "" &&
		base.RawPath == "" &&
		base.User == nil &&
		base.RawQuery == "" &&
		!base.ForceQuery &&
		base.Fragment == "" &&
		base.Opaque == ""
}

// canFastJoinPath reports whether requestPath can be spliced onto an
// upstream base without going through url.Parse + URL.String.
//
// Allowed bytes match what url.URL.String() would emit unescaped:
//   - Alphanumeric and unreserved (-._~).
//   - '/' (never doubled in the path portion).
//   - '?' '#' as single separators between path / query / fragment.
//   - '%' only when followed by two valid hex digits.
//   - In the query and fragment portion: common sub-delims
//     (&=+,;!$*()'). Authority-injection markers ('@' ':') and any
//     other byte are rejected so the slow path can apply Go's stdlib
//     URL escaping rules.
//
// The FuzzJoinUpstreamPath suite covers each rejection boundary.
func canFastJoinPath(requestPath string) bool {
	if requestPath == "" || requestPath[0] != '/' {
		return false
	}
	inPath := true
	var prev byte
	for i := 0; i < len(requestPath); i++ {
		c := requestPath[i]
		if (c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') {
			prev = c
			continue
		}
		switch c {
		case '-', '.', '_', '~':
			// Unreserved — always safe.
		case '/':
			if inPath && prev == '/' {
				return false
			}
		case '?', '#':
			if !inPath {
				// Repeated path/query separator — let slow path handle.
				return false
			}
			if i == len(requestPath)-1 {
				// Empty query/fragment markers are not represented in the
				// slow path's output, so fall back to preserve behavior.
				return false
			}
			inPath = false
		case '%':
			if i+2 >= len(requestPath) || !isHexDigit(requestPath[i+1]) || !isHexDigit(requestPath[i+2]) {
				return false
			}
		case '&', '=', '+', ',', ';', '!', '$', '*', '(', ')', '\'':
			// Sub-delims — only safe inside query/fragment.
			if inPath {
				return false
			}
		default:
			// Everything else falls back to the slow path: authority /
			// scheme separators ('@', ':') we always refuse, plus any
			// byte (spaces, control bytes, brackets, quotes, multi-byte
			// UTF-8, etc.) that url.URL.String() would percent-encode.
			return false
		}
		prev = c
	}
	return true
}

func isHexDigit(b byte) bool {
	return (b >= '0' && b <= '9') || (b >= 'a' && b <= 'f') || (b >= 'A' && b <= 'F')
}

